#!/usr/bin/env python3
"""Durable, tenant-routed Slack notices for actionable engineering jobs.

Python 3.11+ standard library. Import Outbox or use the CLI/loopback ingress.
The event envelope is this adapter's contract; map product job events into it.
"""
from __future__ import annotations

import argparse
import contextlib
import datetime as dt
import hashlib
import hmac
import json
import os
import re
import secrets
import sqlite3
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

ACTION_STATES = {
    "clarification_required": ("Clarification required", "Provide clarification"),
    "execution_blocked": ("Execution needs attention", "Review the next step"),
    "qa_failed": ("QA needs attention", "Review the failed check"),
    "preview_ready": ("Preview ready", "Review the preview"),
    "approval_requested": ("Approval requested", "Review in the dashboard"),
}
ALL_STATES = set(ACTION_STATES) | {"quiet"}
FIELDS = {
    "event_id", "job_id", "store_id", "version", "state", "title",
    "reason", "review_url", "occurred_at",
}
ID = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}$")
ENV = re.compile(r"^[A-Z][A-Z0-9_]{2,127}$")
SLACK_ID = re.compile(r"^[A-Z][A-Z0-9]{7,31}$")
SECRET = re.compile(
    r"(?i)(?:xox[baprs]-[A-Za-z0-9-]{10,}|hooks\.slack(?:-gov)?\.com/services/"
    r"|Bearer\s+\S{8,}|(?:password|api[_-]?key|access[_-]?token|secret)\s*[:=]\s*\S+)"
)
MAX_BODY = 32_768


class InputError(ValueError):
    pass


def compact(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def identifier(value, label):
    if not isinstance(value, str) or not ID.fullmatch(value):
        raise InputError(f"{label} must be a stable identifier of at most 160 characters")
    return value


def text_value(value, label, maximum, required=True):
    if not isinstance(value, str) or len(value) > maximum or (required and not value.strip()):
        raise InputError(f"{label} must contain {'1' if required else '0'}–{maximum} characters")
    if any(ord(c) < 32 and c not in "\n\t" for c in value):
        raise InputError(f"{label} contains control characters")
    if SECRET.search(value):
        raise InputError(f"{label} must contain a short customer-safe summary")
    return value.strip()


def utc_epoch(value):
    if not isinstance(value, str):
        raise InputError("occurred_at must be an ISO 8601 timestamp with a timezone")
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise InputError("occurred_at must be an ISO 8601 timestamp") from exc
    if parsed.tzinfo is None:
        raise InputError("occurred_at requires a timezone")
    return parsed.timestamp()


def safe_review_url(value, origins):
    if not isinstance(value, str) or len(value) > 1500:
        raise InputError("review_url must be an authenticated dashboard URL")
    p = urllib.parse.urlsplit(value)
    if p.scheme != "https" or not p.hostname or p.username or p.password or p.query or p.fragment:
        raise InputError("review_url must be HTTPS and contain no credentials, query, or fragment")
    try:
        port = p.port
    except ValueError as exc:
        raise InputError("review_url has an invalid port") from exc
    origin = f"https://{p.hostname.lower()}" + (f":{port}" if port and port != 443 else "")
    if origin not in origins:
        raise InputError("review_url origin is not configured for this tenant")
    if any(c.isspace() or ord(c) < 32 or c in "<>|" for c in value):
        raise InputError("review_url contains whitespace or message markup delimiters")
    return value


def load_config(path):
    config = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(config, dict) or config.get("version") != 1:
        raise InputError("config.version must be 1")
    if set(config) - {"version", "product_name", "tenants", "routes"}:
        raise InputError("config has unknown fields")
    config["product_name"] = text_value(config.get("product_name", "TaskerArmy"), "product_name", 60)
    tenants = config.get("tenants")
    routes = config.get("routes")
    if not isinstance(tenants, dict) or not isinstance(routes, list):
        raise InputError("config requires a tenants object and routes list")
    ingress_references = set()
    for tenant, value in tenants.items():
        identifier(tenant, "tenant_id")
        if not isinstance(value, dict) or set(value) - {"ingress_token_env", "review_origins"}:
            raise InputError(f"invalid tenant settings for {tenant}")
        key = value.get("ingress_token_env")
        if not isinstance(key, str) or not ENV.fullmatch(key):
            raise InputError(f"{tenant} needs an ingress_token_env reference")
        if key in ingress_references:
            raise InputError("each tenant requires a distinct ingress_token_env reference")
        ingress_references.add(key)
        origins = value.get("review_origins")
        if not isinstance(origins, list) or not origins:
            raise InputError(f"{tenant} needs at least one review origin")
        for origin in origins:
            p = urllib.parse.urlsplit(origin) if isinstance(origin, str) else None
            if not p or p.scheme != "https" or not p.hostname or p.username or p.password:
                raise InputError("review origins must be HTTPS origins")
            if p.path or p.query or p.fragment or origin.endswith(":443"):
                raise InputError("review origins must use the canonical origin without a slash")
    seen = set()
    for route in routes:
        allowed = {"id", "tenant_id", "store_ids", "states", "team_id", "channel_id",
                   "webhook_env", "generation", "enabled"}
        if not isinstance(route, dict) or set(route) - allowed:
            raise InputError("route has unknown fields")
        rid = identifier(route.get("id"), "route.id")
        if rid in seen:
            raise InputError(f"duplicate route id: {rid}")
        seen.add(rid)
        if route.get("tenant_id") not in tenants:
            raise InputError(f"route {rid} has no configured tenant")
        stores = route.get("store_ids")
        if not isinstance(stores, list) or not stores:
            raise InputError(f"route {rid} requires store_ids; use ['*'] for all stores")
        for store in stores:
            if store != "*":
                identifier(store, "store_id")
        if "*" in stores and len(stores) != 1:
            raise InputError("the all-stores selector cannot be mixed with store ids")
        states = route.get("states")
        if (not isinstance(states, list) or not states
                or any(not isinstance(s, str) or s not in ACTION_STATES for s in states)):
            raise InputError(f"route {rid} requires supported actionable states")
        for field in ("team_id", "channel_id"):
            if not isinstance(route.get(field), str) or not SLACK_ID.fullmatch(route[field]):
                raise InputError(f"route {rid} requires the Slack installation's {field}")
        if not isinstance(route.get("webhook_env"), str) or not ENV.fullmatch(route["webhook_env"]):
            raise InputError(f"route {rid} requires a webhook_env reference")
        if type(route.get("generation")) is not int or route["generation"] < 1:
            raise InputError(f"route {rid} requires a positive generation")
        if type(route.get("enabled")) is not bool:
            raise InputError(f"route {rid} requires enabled=true or false")
    return config


def route_fingerprint(route):
    return hashlib.sha256(compact(route).encode("utf-8")).hexdigest()


def validate_event(tenant_id, event, config, now):
    if tenant_id not in config["tenants"]:
        raise InputError("tenant is not configured")
    if not isinstance(event, dict) or set(event) - FIELDS:
        raise InputError("event contains unknown fields")
    required = FIELDS - {"reason"}
    if required - set(event):
        raise InputError("event is missing: " + ", ".join(sorted(required - set(event))))
    cleaned = dict(event)
    for key in ("event_id", "job_id", "store_id"):
        identifier(cleaned[key], key)
    if type(cleaned["version"]) is not int or not 1 <= cleaned["version"] <= 9_223_372_036_854_775_807:
        raise InputError("version must be the positive monotonically increasing job revision")
    if not isinstance(cleaned["state"], str) or cleaned["state"] not in ALL_STATES:
        raise InputError("state is not supported")
    cleaned["title"] = text_value(cleaned["title"], "title", 180)
    cleaned["reason"] = text_value(cleaned.get("reason", ""), "reason", 500, required=False)
    cleaned["review_url"] = safe_review_url(
        cleaned["review_url"], config["tenants"][tenant_id]["review_origins"]
    )
    occurred = utc_epoch(cleaned["occurred_at"])
    if occurred > now + 300:
        raise InputError("occurred_at is more than five minutes in the future")
    return cleaned, occurred


def slack_escape(value):
    return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def slack_payload(event, product_name):
    state = event["state"]
    if state not in ACTION_STATES:
        raise InputError("quiet events have no Slack payload")
    label, action = ACTION_STATES[state]
    summary = event["reason"] or action
    title = f"{product_name}: {label}"
    detail = f'{event["title"]}\nStore: {event["store_id"]}\n{summary}'
    return {
        "text": slack_escape(f'{title} — {event["title"]}. {summary} {event["review_url"]}'),
        "mrkdwn": False,
        "unfurl_links": False,
        "unfurl_media": False,
        "blocks": [
            {"type": "header", "text": {"type": "plain_text", "text": title, "emoji": False}},
            {"type": "section", "text": {"type": "plain_text", "text": detail, "emoji": False}},
            {"type": "context", "elements": [
                {"type": "plain_text",
                 "text": f'Job {event["job_id"]} · revision {event["version"]}',
                 "emoji": False}
            ]},
            {"type": "section", "text": {
                "type": "mrkdwn", "verbatim": True,
                "text": f'<{slack_escape(event["review_url"])}|{action}>'
            }},
        ],
    }


SCHEMA = """
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER NOT NULL);
INSERT INTO schema_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM schema_version);
CREATE TABLE IF NOT EXISTS events(
 tenant_id TEXT NOT NULL, event_id TEXT NOT NULL, payload_hash TEXT NOT NULL,
 job_id TEXT NOT NULL, version INTEGER NOT NULL, received_at REAL NOT NULL,
 outcome TEXT NOT NULL, state TEXT NOT NULL, event_json TEXT NOT NULL,
 PRIMARY KEY(tenant_id,event_id), UNIQUE(tenant_id,job_id,version));
CREATE TABLE IF NOT EXISTS jobs(
 tenant_id TEXT NOT NULL, job_id TEXT NOT NULL, store_id TEXT NOT NULL,
 version INTEGER NOT NULL, event_id TEXT NOT NULL, state TEXT NOT NULL,
 updated_at REAL NOT NULL, PRIMARY KEY(tenant_id,job_id));
CREATE TABLE IF NOT EXISTS deliveries(
 id INTEGER PRIMARY KEY, tenant_id TEXT NOT NULL, route_id TEXT NOT NULL,
 route_fingerprint TEXT NOT NULL, channel_key TEXT NOT NULL,
 event_id TEXT NOT NULL, job_id TEXT NOT NULL, version INTEGER NOT NULL,
 event_json TEXT NOT NULL, message_json TEXT NOT NULL, message_sha256 TEXT NOT NULL,
 status TEXT NOT NULL, due_at REAL NOT NULL,
 expires_at REAL NOT NULL, created_at REAL NOT NULL, updated_at REAL NOT NULL,
 attempts INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_until REAL,
 last_error TEXT, http_status INTEGER, sent_at REAL, resolution TEXT,
 UNIQUE(tenant_id,route_id,event_id));
CREATE INDEX IF NOT EXISTS due_deliveries ON deliveries(status,due_at);
CREATE TABLE IF NOT EXISTS channels(channel_key TEXT PRIMARY KEY, next_allowed REAL NOT NULL);
CREATE TABLE IF NOT EXISTS route_failures(
 route_id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, reason TEXT NOT NULL,
 failed_at REAL NOT NULL);
"""


class Outbox:
    def __init__(self, database, config_path):
        self.database = str(database)
        self.config_path = str(config_path)
        self.config = load_config(config_path)
        path = Path(database)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            try:
                fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            except FileExistsError:
                pass
            else:
                os.close(fd)
        with contextlib.closing(self.connect()) as db:
            db.executescript(SCHEMA)
            versions = [r[0] for r in db.execute("SELECT version FROM schema_version")]
            if versions != [1]:
                raise InputError("unsupported database schema version")

    def connect(self):
        db = sqlite3.connect(self.database, timeout=10, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=FULL")
        db.execute("PRAGMA busy_timeout=10000")
        return db

    @contextlib.contextmanager
    def transaction(self):
        db = self.connect()
        try:
            db.execute("BEGIN IMMEDIATE")
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    def record(self, tenant_id, event, ttl_seconds=86400):
        if type(ttl_seconds) is not int or not 60 <= ttl_seconds <= 604800:
            raise InputError("ttl_seconds must be 60–604800")
        config = load_config(self.config_path)
        now = time.time()
        event, occurred = validate_event(tenant_id, event, config, now)
        payload = compact(event)
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        with self.transaction() as db:
            prior = db.execute(
                "SELECT payload_hash,outcome FROM events WHERE tenant_id=? AND event_id=?",
                (tenant_id, event["event_id"])).fetchone()
            if prior:
                if prior["payload_hash"] != digest:
                    raise InputError("event_id was already used for different content")
                return {"outcome": "duplicate", "original_outcome": prior["outcome"], "queued": 0}
            revision = db.execute(
                "SELECT event_id FROM events WHERE tenant_id=? AND job_id=? AND version=?",
                (tenant_id, event["job_id"], event["version"])).fetchone()
            if revision:
                raise InputError("job version was already used by a different event")
            current = db.execute(
                "SELECT * FROM jobs WHERE tenant_id=? AND job_id=?",
                (tenant_id, event["job_id"])).fetchone()
            if current and current["store_id"] != event["store_id"]:
                raise InputError("a job cannot move between stores")
            if current and event["version"] == current["version"]:
                raise InputError("job version was already used by a different event")
            stale = bool(current and event["version"] < current["version"])
            expired = occurred + ttl_seconds <= now
            outcome = "stale" if stale else ("expired" if expired else "recorded")
            db.execute("INSERT INTO events VALUES(?,?,?,?,?,?,?,?,?)",
                       (tenant_id, event["event_id"], digest, event["job_id"],
                        event["version"], now, outcome, event["state"], payload))
            if stale:
                return {"outcome": outcome, "queued": 0}
            db.execute("""
                INSERT INTO jobs VALUES(?,?,?,?,?,?,?)
                ON CONFLICT(tenant_id,job_id) DO UPDATE SET
                 version=excluded.version,event_id=excluded.event_id,state=excluded.state,
                 updated_at=excluded.updated_at""",
                (tenant_id, event["job_id"], event["store_id"], event["version"],
                 event["event_id"], event["state"], now))
            db.execute("""UPDATE deliveries SET status='superseded',updated_at=?
                WHERE tenant_id=? AND job_id=? AND version<? AND status IN ('pending','failed')""",
                (now, tenant_id, event["job_id"], event["version"]))
            count = 0
            destinations = set()
            if not expired and event["state"] in ACTION_STATES:
                message = compact(slack_payload(event, config["product_name"]))
                message_sha = hashlib.sha256(message.encode("utf-8")).hexdigest()
                for route in config["routes"]:
                    if not route["enabled"] or route["tenant_id"] != tenant_id:
                        continue
                    if "*" not in route["store_ids"] and event["store_id"] not in route["store_ids"]:
                        continue
                    if event["state"] not in route["states"]:
                        continue
                    channel_key = route["team_id"] + ":" + route["channel_id"]
                    if channel_key in destinations:
                        continue
                    destinations.add(channel_key)
                    db.execute("""
                        INSERT INTO deliveries(tenant_id,route_id,route_fingerprint,channel_key,
                          event_id,job_id,version,event_json,message_json,message_sha256,
                          status,due_at,expires_at,created_at,updated_at)
                        VALUES(?,?,?,?,?,?,?,?,?,?,'pending',?,?,?,?)""",
                        (tenant_id, route["id"], route_fingerprint(route),
                         channel_key, event["event_id"],
                         event["job_id"], event["version"], payload, message, message_sha, now,
                         occurred + ttl_seconds, now, now))
                    count += 1
            return {"outcome": outcome, "queued": count}

    def _claim(self):
        config = load_config(self.config_path)
        routes = {r["id"]: r for r in config["routes"]}
        now = time.time()
        with self.transaction() as db:
            db.execute("""UPDATE deliveries SET status='uncertain',last_error='worker_interrupted',
                updated_at=? WHERE status='dispatching' AND lease_until<=?""", (now, now))
            db.execute("""UPDATE deliveries SET status='expired',updated_at=?
                WHERE status='pending' AND expires_at<=?""", (now, now))
            for failure in db.execute("SELECT route_id,fingerprint FROM route_failures").fetchall():
                current_route = routes.get(failure["route_id"])
                if (not current_route or not current_route["enabled"]
                        or route_fingerprint(current_route) != failure["fingerprint"]):
                    db.execute("DELETE FROM route_failures WHERE route_id=?", (failure["route_id"],))
            rows = db.execute("""SELECT d.* FROM deliveries d
                WHERE d.status='pending' AND d.due_at<=? AND NOT EXISTS (
                  SELECT 1 FROM route_failures f WHERE f.route_id=d.route_id
                    AND f.fingerprint=d.route_fingerprint)
                AND NOT EXISTS (SELECT 1 FROM channels c WHERE c.channel_key=d.channel_key
                    AND c.next_allowed>?)
                ORDER BY d.due_at,d.id LIMIT 200""",
                (now, now)).fetchall()
            for row in rows:
                route = routes.get(row["route_id"])
                if not route or not route["enabled"] or route_fingerprint(route) != row["route_fingerprint"]:
                    db.execute("UPDATE deliveries SET status='route_changed',updated_at=? WHERE id=?",
                               (now, row["id"]))
                    continue
                try:
                    retained_event = json.loads(row["event_json"])
                    safe_review_url(
                        retained_event["review_url"],
                        config["tenants"][row["tenant_id"]]["review_origins"],
                    )
                except InputError:
                    db.execute("UPDATE deliveries SET status='route_changed',"
                               "last_error='review_origin_changed',updated_at=? WHERE id=?",
                               (now, row["id"]))
                    continue
                latest = db.execute("SELECT version FROM jobs WHERE tenant_id=? AND job_id=?",
                                    (row["tenant_id"], row["job_id"])).fetchone()
                if not latest or latest["version"] != row["version"]:
                    db.execute("UPDATE deliveries SET status='superseded',updated_at=? WHERE id=?",
                               (now, row["id"]))
                    continue
                failure = db.execute("SELECT fingerprint FROM route_failures WHERE route_id=?",
                                     (route["id"],)).fetchone()
                if failure and failure["fingerprint"] == row["route_fingerprint"]:
                    continue
                throttle = db.execute("SELECT next_allowed FROM channels WHERE channel_key=?",
                                      (row["channel_key"],)).fetchone()
                if throttle and throttle["next_allowed"] > now:
                    db.execute("UPDATE deliveries SET due_at=? WHERE id=?",
                               (throttle["next_allowed"], row["id"]))
                    continue
                token = secrets.token_hex(16)
                db.execute("""UPDATE deliveries SET status='dispatching',attempts=attempts+1,
                    lease_token=?,lease_until=?,updated_at=? WHERE id=?""",
                    (token, now + 45, now, row["id"]))
                db.execute("""INSERT INTO channels VALUES(?,?)
                    ON CONFLICT(channel_key) DO UPDATE SET next_allowed=excluded.next_allowed""",
                    (row["channel_key"], now + 1.1))
                claimed = dict(row)
                claimed.update(lease_token=token, attempts=row["attempts"] + 1)
                return claimed, route
        return None

    def _finish(self, row, outcome, http_status=None, code=None, retry_after=None):
        now = time.time()
        due = now
        if outcome == "retry":
            due = now + (retry_after if retry_after is not None else min(3600, 30 * 2 ** min(row["attempts"], 7)))
            status = "failed" if row["attempts"] >= 8 and retry_after is None else "pending"
        else:
            status = outcome
        with self.transaction() as db:
            changed = db.execute("""UPDATE deliveries SET status=?,due_at=?,updated_at=?,
                last_error=?,http_status=?,sent_at=?,lease_token=NULL,lease_until=NULL
                WHERE id=? AND status='dispatching' AND lease_token=?""",
                (status, due, now, code, http_status, now if status == "sent" else None,
                 row["id"], row["lease_token"])).rowcount
            if changed != 1:
                raise RuntimeError("delivery lease was lost; inspect the retained delivery")
            if retry_after is not None:
                db.execute("""INSERT INTO channels VALUES(?,?) ON CONFLICT(channel_key)
                    DO UPDATE SET next_allowed=MAX(next_allowed,excluded.next_allowed)""",
                    (row["channel_key"], due))
            if outcome == "route_failed":
                db.execute("""INSERT INTO route_failures VALUES(?,?,?,?)
                    ON CONFLICT(route_id) DO UPDATE SET fingerprint=excluded.fingerprint,
                    reason=excluded.reason,failed_at=excluded.failed_at""",
                    (row["route_id"], row["route_fingerprint"], code or "route_failed", now))
        return {"delivery_id": row["id"], "status": status, "http_status": http_status, "error": code}

    def deliver_one(self):
        claim = self._claim()
        if claim is None:
            return None
        row, route = claim
        secret = os.environ.get(route["webhook_env"], "")
        try:
            p = urllib.parse.urlsplit(secret)
            valid = (p.scheme == "https" and p.hostname in {"hooks.slack.com", "hooks.slack-gov.com"}
                     and not p.username and not p.password and p.port in (None, 443)
                     and not p.query and not p.fragment
                     and re.fullmatch(r"/services/[A-Za-z0-9]+/[A-Za-z0-9]+/[A-Za-z0-9]+", p.path))
        except ValueError:
            valid = False
        if not valid:
            return self._finish(row, "route_failed", code="webhook_configuration")
        body = row["message_json"].encode("utf-8")
        if hashlib.sha256(body).hexdigest() != row["message_sha256"]:
            return self._finish(row, "failed", code="retained_message_digest_mismatch")
        request = urllib.request.Request(secret, data=body, method="POST",
                                         headers={"Content-Type": "application/json; charset=utf-8"})
        opener = urllib.request.build_opener(NoRedirect)
        try:
            with opener.open(request, timeout=12) as response:
                status = response.status
                answer = response.read(4096).decode("utf-8", errors="replace").strip()
        except urllib.error.HTTPError as exc:
            status = exc.code
            rejection = ""
            try:
                answer = exc.read(256).decode("utf-8", errors="replace").strip()
                if answer in {"invalid_payload", "user_not_found", "action_prohibited",
                              "channel_not_found", "channel_is_archived", "no_service",
                              "no_service_id", "no_team", "team_disabled", "invalid_token",
                              "no_active_hooks", "no_text", "posting_to_general_channel_denied",
                              "too_many_attachments"}:
                    rejection = answer
            except (OSError, TimeoutError):
                pass
            finally:
                exc.close()
            if status == 429:
                raw = exc.headers.get("Retry-After", "")
                retry = int(raw) if raw.isdecimal() else 60
                return self._finish(row, "retry", status, "rate_limited", max(1, retry))
            if 500 <= status < 600:
                return self._finish(row, "retry", status, "slack_server_error")
            if status in (400, 401, 403, 404, 410):
                return self._finish(row, "route_failed", status, rejection or "slack_rejected_route_or_payload")
            return self._finish(row, "failed", status, "unexpected_http_response")
        except (urllib.error.URLError, TimeoutError, OSError):
            return self._finish(row, "uncertain", code="transport_outcome_unknown")
        if status == 200 and answer == "ok":
            return self._finish(row, "sent", status)
        return self._finish(row, "uncertain", status, "unexpected_acknowledgement")

    def status(self, tenant=None, limit=100):
        with contextlib.closing(self.connect()) as db:
            where, args = ("WHERE tenant_id=?", [tenant]) if tenant else ("", [])
            counts = [dict(r) for r in db.execute(
                f"SELECT status,COUNT(*) AS count FROM deliveries {where} GROUP BY status", args)]
            rows = [dict(r) for r in db.execute(f"""SELECT id,tenant_id,route_id,event_id,job_id,
                version,channel_key,message_sha256,status,attempts,due_at,expires_at,
                updated_at,http_status,last_error,sent_at,resolution
                FROM deliveries {where} ORDER BY id DESC LIMIT ?""", [*args, min(max(limit, 1), 1000)])]
            route_ids = {r["id"] for r in load_config(self.config_path)["routes"]
                         if tenant is None or r["tenant_id"] == tenant}
            failures = [dict(r) for r in db.execute(
                "SELECT route_id,reason,failed_at FROM route_failures") if r["route_id"] in route_ids]
            return {"counts": counts, "deliveries": rows, "route_failures": failures}

    def inspect(self, delivery_id):
        with contextlib.closing(self.connect()) as db:
            row = db.execute("SELECT * FROM deliveries WHERE id=?", (delivery_id,)).fetchone()
            if row is None:
                raise InputError("delivery_id does not exist")
            result = dict(row)
            result["event"] = json.loads(result.pop("event_json"))
            result["message"] = json.loads(result.pop("message_json"))
            result.pop("lease_token", None)
            return result

    def job_timeline(self, tenant_id, job_id, before_version=None, limit=100):
        identifier(tenant_id, "tenant_id")
        identifier(job_id, "job_id")
        if tenant_id not in load_config(self.config_path)["tenants"]:
            raise InputError("tenant is not configured")
        if type(limit) is not int or not 1 <= limit <= 1000:
            raise InputError("limit must be 1–1000")
        if before_version is not None and (type(before_version) is not int or before_version < 1):
            raise InputError("before_version must be a positive revision")
        with contextlib.closing(self.connect()) as db:
            job = db.execute("SELECT * FROM jobs WHERE tenant_id=? AND job_id=?",
                             (tenant_id, job_id)).fetchone()
            args = [tenant_id, job_id]
            prior = ""
            if before_version is not None:
                prior = " AND version<?"
                args.append(before_version)
            events = [dict(r) for r in db.execute(
                "SELECT event_id,version,state,received_at,outcome,payload_hash FROM events "
                "WHERE tenant_id=? AND job_id=?" + prior + " ORDER BY version DESC LIMIT ?",
                [*args, limit + 1])]
            more = len(events) > limit
            events = events[:limit]
            for event in events:
                event["deliveries"] = [dict(r) for r in db.execute(
                    "SELECT id,route_id,channel_key,status,attempts,http_status,last_error,"
                    "sent_at,resolution,message_sha256 FROM deliveries "
                    "WHERE tenant_id=? AND event_id=? ORDER BY id",
                    (tenant_id, event["event_id"]))]
            return {"job": dict(job) if job else None, "events": events,
                    "next_before_version": events[-1]["version"] if more else None}

    def resume_route(self, route_id):
        route = next((r for r in load_config(self.config_path)["routes"] if r["id"] == route_id), None)
        if not route or not route["enabled"]:
            raise InputError("enable and correct the configured route before resuming it")
        fingerprint = route_fingerprint(route)
        with self.transaction() as db:
            db.execute("DELETE FROM route_failures WHERE route_id=?", (route_id,))
            updated = db.execute("""UPDATE deliveries SET status='pending',due_at=?,updated_at=?,
                last_error=NULL WHERE route_id=? AND route_fingerprint=? AND status='route_failed'""",
                (time.time(), time.time(), route_id, fingerprint)).rowcount
        return {"route_id": route_id, "resumed": updated}

    def resolve(self, delivery_id, outcome, note):
        if outcome not in {"sent", "retry", "cancelled"}:
            raise InputError("resolution must be sent, retry, or cancelled")
        note = text_value(note, "resolution note", 300)
        with self.transaction() as db:
            row = db.execute("SELECT * FROM deliveries WHERE id=?", (delivery_id,)).fetchone()
            if not row or row["status"] not in {"uncertain", "failed", "route_changed", "route_failed"}:
                raise InputError("only uncertain, failed, or changed-route deliveries can be resolved")
            if outcome == "retry":
                route = next((r for r in load_config(self.config_path)["routes"]
                              if r["id"] == row["route_id"]), None)
                if not route or route_fingerprint(route) != row["route_fingerprint"]:
                    raise InputError("retry requires the original route; ingest a new revision for a new destination")
            status = "pending" if outcome == "retry" else outcome
            db.execute("""UPDATE deliveries SET status=?,due_at=?,updated_at=?,resolution=?,
                attempts=CASE WHEN ?='pending' THEN 0 ELSE attempts END,
                sent_at=CASE WHEN ?='sent' THEN ? ELSE sent_at END WHERE id=?""",
                (status, time.time(), time.time(), note, status, status, time.time(), delivery_id))
        return {"delivery_id": delivery_id, "status": status}


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def serve(outbox, host, port):
    class Handler(BaseHTTPRequestHandler):
        server_version = "JobNotice/1"
        def log_message(self, format, *args):
            return

        def reply(self, code, value):
            body = compact(value).encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self):
            if self.path == "/healthz":
                self.reply(200, {"status": "ready"})
            else:
                self.reply(404, {"error": "not_found"})

        def do_POST(self):
            if self.path != "/v1/events":
                self.reply(404, {"error": "not_found"})
                return
            try:
                config = load_config(outbox.config_path)
                tenant = self.headers.get("X-Notification-Tenant", "")
                definition = config["tenants"].get(tenant)
                expected = os.environ.get(definition["ingress_token_env"], "") if definition else ""
                supplied = self.headers.get("Authorization", "")
                if len(expected) < 32 or not hmac.compare_digest(supplied, "Bearer " + expected):
                    self.reply(401, {"error": "invalid_ingress_authorization"})
                    return
                if self.headers.get("Transfer-Encoding") is not None:
                    raise InputError("chunked request bodies are not supported")
                if self.headers.get_content_type() != "application/json":
                    self.reply(415, {"error": "application_json_required"})
                    return
                raw_length = self.headers.get("Content-Length", "")
                if not raw_length.isdecimal() or not 1 <= int(raw_length) <= MAX_BODY:
                    self.reply(413, {"error": "request_body_limit", "limit_bytes": MAX_BODY})
                    return
                self.connection.settimeout(10)
                raw = self.rfile.read(int(raw_length))
                if len(raw) != int(raw_length):
                    raise InputError("request body is incomplete")
                result = outbox.record(tenant, json.loads(raw.decode("utf-8")))
                self.reply(202, result)
            except (InputError, ValueError, UnicodeError) as exc:
                self.reply(400, {"error": "invalid_event", "detail": str(exc)[:300]})
            except (sqlite3.Error, OSError):
                self.reply(503, {"error": "ingress_unavailable_retry_same_event_id"})
    ThreadingHTTPServer((host, port), Handler).serve_forever()


def read_event(path):
    return json.loads(sys.stdin.read() if path == "-" else Path(path).read_text(encoding="utf-8"))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--db", default="state/notices.sqlite3")
    parser.add_argument("--config", default="notices.json")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("init", help="Create an empty private configuration and database")
    p = sub.add_parser("ingest", help="Record one real product job revision")
    p.add_argument("--tenant", required=True)
    p.add_argument("--event", required=True, help="UTF-8 JSON path or - for stdin")
    p = sub.add_parser("render", help="Render a real event as a Slack JSON message")
    p.add_argument("--tenant", required=True)
    p.add_argument("--event", required=True)
    p = sub.add_parser("deliver", help="Deliver currently due notifications")
    p.add_argument("--limit", type=int, default=100)
    p = sub.add_parser("run", help="Run the delivery worker continuously")
    p.add_argument("--interval", type=float, default=2.0)
    p = sub.add_parser("status", help="Inspect saved delivery outcomes")
    p.add_argument("--tenant")
    p.add_argument("--limit", type=int, default=100)
    p = sub.add_parser("timeline", help="Read a job revision history and its delivery outcomes")
    p.add_argument("--tenant", required=True)
    p.add_argument("--job", required=True)
    p.add_argument("--before-version", type=int)
    p.add_argument("--limit", type=int, default=100)
    p = sub.add_parser("inspect", help="Read one retained event, exact message and destination")
    p.add_argument("delivery_id", type=int)
    p = sub.add_parser("resume-route", help="Resume delivery after correcting Slack installation settings")
    p.add_argument("route_id")
    p = sub.add_parser("resolve", help="Reconcile an uncertain or failed delivery using its actual outcome")
    p.add_argument("delivery_id", type=int)
    p.add_argument("outcome", choices=["sent", "retry", "cancelled"])
    p.add_argument("--note", required=True)
    p = sub.add_parser("serve", help="Run authenticated loopback event ingress")
    p.add_argument("--host", default="127.0.0.1")
    p.add_argument("--port", type=int, default=8094)
    args = parser.parse_args(argv)
    if args.command == "init":
        config_path = Path(args.config)
        config_path.parent.mkdir(parents=True, exist_ok=True)
        with os.fdopen(os.open(config_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600), "w", encoding="utf-8") as f:
            f.write(json.dumps({"version": 1, "product_name": "TaskerArmy", "tenants": {}, "routes": []}, indent=2) + "\n")
    outbox = Outbox(args.db, args.config)
    if args.command == "init":
        result = {"database": args.db, "config": args.config, "status": "initialized"}
    elif args.command in {"ingest", "render"}:
        event = read_event(args.event)
        if args.command == "ingest":
            result = outbox.record(args.tenant, event)
        else:
            event, _ = validate_event(args.tenant, event, outbox.config, time.time())
            result = slack_payload(event, outbox.config["product_name"])
    elif args.command == "status":
        result = outbox.status(args.tenant, args.limit)
    elif args.command == "timeline":
        result = outbox.job_timeline(args.tenant, args.job, args.before_version, args.limit)
    elif args.command == "inspect":
        result = outbox.inspect(args.delivery_id)
    elif args.command == "resolve":
        result = outbox.resolve(args.delivery_id, args.outcome, args.note)
    elif args.command == "resume-route":
        result = outbox.resume_route(args.route_id)
    elif args.command == "serve":
        serve(outbox, args.host, args.port)
        return 0
    elif args.command == "run":
        if not 0.1 <= args.interval <= 60:
            raise InputError("interval must be 0.1–60 seconds")
        while True:
            result = outbox.deliver_one()
            if result is not None:
                print(compact(result), flush=True)
            else:
                time.sleep(args.interval)
    else:
        if not 1 <= args.limit <= 1000:
            raise InputError("limit must be 1–1000")
        result = []
        for _ in range(args.limit):
            item = outbox.deliver_one()
            if item is None:
                break
            result.append(item)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        raise SystemExit(130)
    except (InputError, FileExistsError, json.JSONDecodeError) as exc:
        print(compact({"error": str(exc)}), file=sys.stderr)
        raise SystemExit(2)

#!/usr/bin/env python3
"""Local operator console for the maintained TaskerArmy notification outbox."""
from __future__ import annotations

import argparse
import base64
import contextlib
import fcntl
import hashlib
import hmac
import json
import os
from pathlib import Path
import re
import secrets
import sys
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlsplit

from notification_outbox import Outbox, InputError, load_config

MAX_BODY = 256 * 1024
MATERIAL_ROUTE_FIELDS = ("tenant_id", "store_ids", "states", "team_id",
                         "channel_id", "webhook_env")
RESOLVABLE = {"uncertain", "failed", "route_changed", "route_failed"}


class OperatorError(Exception):
    def __init__(self, status, code, message):
        super().__init__(message)
        self.status, self.code = status, code


def revision(raw):
    return hashlib.sha256(raw).hexdigest()


def exact_fields(value, allowed, label):
    if not isinstance(value, dict):
        raise InputError(label + " must be an object")
    unexpected = set(value) - set(allowed)
    if unexpected:
        raise InputError(label + " contains unsupported fields: " +
                         ", ".join(sorted(unexpected)))


def checked_document(config):
    exact_fields(config, {"version", "product_name", "tenants", "routes"},
                 "Configuration")
    tenants, routes = config.get("tenants"), config.get("routes")
    if not isinstance(tenants, dict) or not isinstance(routes, list):
        raise InputError("Configuration requires tenants and routes")
    for tenant_id, tenant in tenants.items():
        exact_fields(tenant, {"ingress_token_env", "review_origins"},
                     "Tenant " + str(tenant_id))
    for route in routes:
        exact_fields(route, {"id", *MATERIAL_ROUTE_FIELDS, "generation", "enabled"},
                     "Route")
    return config


def read_configuration(path):
    # Validate the same exact snapshot whose hash is returned. The loader reads
    # a temporary private file so an atomic concurrent replacement cannot make
    # the returned document and preimage refer to different revisions.
    raw = path.read_bytes()
    config = checked_document(json.loads(raw))
    fd, name = tempfile.mkstemp(prefix=".operator-read-", suffix=".json",
                                dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(raw)
        load_config(name)
    finally:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(name)
    return config, revision(raw)


def save_configuration(path, expected, incoming):
    if not isinstance(expected, str) or not re.fullmatch(r"[0-9a-f]{64}", expected):
        raise InputError("Supply the configuration revision you opened")
    checked_document(incoming)
    encoded = (json.dumps(incoming, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    if len(encoded) > MAX_BODY:
        raise InputError("Configuration is too large")
    # Cooperating operator writers share the lock; manual edits are composed
    # using the current revision. os.replace gives readers a complete document.
    lock_path = path.with_name(path.name + ".operator.lock")
    with open(lock_path, "a+b") as lock:
        os.chmod(lock_path, 0o600)
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
        before = path.read_bytes()
        if not hmac.compare_digest(revision(before), expected):
            raise OperatorError(409, "configuration_changed",
                                "Configuration changed. Reload it and compose your edit.")
        previous = checked_document(json.loads(before))
        old_routes = {row["id"]: row for row in previous["routes"]}
        for route in incoming["routes"]:
            old = old_routes.get(route.get("id"))
            generation = route.get("generation")
            if old and (type(generation) is not int or generation < old["generation"]):
                raise InputError("Route generation cannot decrease: " +
                                 str(route.get("id")))
            if old and any(old.get(key) != route.get(key)
                           for key in MATERIAL_ROUTE_FIELDS):
                if (not isinstance(generation, int) or isinstance(generation, bool)
                        or generation <= old.get("generation", 0)):
                    raise InputError("Changed routing requires a higher generation: " +
                                     str(route.get("id")))
        fd, name = tempfile.mkstemp(prefix=".operator-write-", suffix=".json",
                                    dir=path.parent)
        try:
            with os.fdopen(fd, "wb") as output:
                output.write(encoded)
                output.flush()
                os.fsync(output.fileno())
            load_config(name)
            # A second preimage read catches a noncooperating editor that wrote
            # while validation ran. Deployment tools should use this API/lock.
            if path.read_bytes() != before:
                raise OperatorError(409, "configuration_changed",
                                    "Configuration changed during validation. Reload it.")
            os.chmod(name, 0o600)
            os.replace(name, path)
            directory = os.open(str(path.parent), os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            with contextlib.suppress(FileNotFoundError):
                os.unlink(name)
    return revision(encoded)


def public_configuration(path):
    config, current = read_configuration(path)
    return {
        "configuration": config,
        "revision": current,
        "credentials": {
            "tenants": {key: bool(os.environ.get(row["ingress_token_env"]))
                        for key, row in config["tenants"].items()},
            "routes": {row["id"]: bool(os.environ.get(row["webhook_env"]))
                       for row in config["routes"]},
        },
    }


def safe_delivery(row):
    if not isinstance(row, dict):
        raise OperatorError(404, "delivery_not_found", "Delivery was not found")
    fields = (
        "id", "tenant_id", "route_id", "event_id", "job_id", "store_id", "version",
        "channel_key", "message_sha256", "status", "attempts", "due_at",
        "expires_at", "updated_at", "http_status", "last_error", "sent_at",
        "resolution", "event", "message",
    )
    result = {key: row[key] for key in fields if key in row}
    result["can_resolve"] = row.get("status") in RESOLVABLE
    return result


def scalar(query, key, default=None):
    rows = query.get(key)
    if rows is None:
        return default
    if len(rows) != 1:
        raise InputError("Supply one " + key)
    return rows[0]


def integer(value, label, minimum=1, maximum=1000):
    if not isinstance(value, str) or not re.fullmatch(r"\d+", value):
        raise InputError(label + " must be an integer")
    parsed = int(value)
    if parsed < minimum or parsed > maximum:
        raise InputError(label + " is outside the supported range")
    return parsed


def identifier(value, label):
    if not isinstance(value, str) or not value.strip() or len(value) > 256:
        raise InputError(label + " is required")
    if any(ord(char) < 32 for char in value):
        raise InputError(label + " contains control characters")
    return value



def delivery_key(value):
    if type(value) is int:
        number = value
    elif isinstance(value, str) and re.fullmatch(r"\d+", value):
        number = int(value)
    else:
        raise InputError("delivery_id must be the saved numeric delivery identifier")
    if not 1 <= number <= 2**63 - 1:
        raise InputError("delivery_id is outside the saved identifier range")
    return number


def browser_record(value, field=None):
    # Python/SQLite revisions remain exact when a browser follows a cursor.
    if isinstance(value, dict):
        return {key: browser_record(item, key) for key, item in value.items()}
    if isinstance(value, list):
        return [browser_record(item) for item in value]
    if type(value) is int and field in {"id", "delivery_id", "version", "next_before_version"}:
        return str(value)
    return value


class OperatorServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, port, database, config, token, html):
        super().__init__(("127.0.0.1", port), OperatorHandler)
        self.database, self.config, self.token, self.html = database, config, token, html
        self._outbox = Outbox(str(database), str(config))
        self.origin = "http://127.0.0.1:" + str(self.server_port)
        hashes = []
        for tag in ("script", "style"):
            for source in re.findall(r"<" + tag + r"(?:\s[^>]*)?>(.*?)</" + tag + ">",
                                     html.decode("utf-8"), re.S | re.I):
                digest = base64.b64encode(hashlib.sha256(source.encode("utf-8")).digest()).decode()
                hashes.append((tag, "'sha256-" + digest + "'"))
        scripts = " ".join(value for kind, value in hashes if kind == "script")
        styles = " ".join(value for kind, value in hashes if kind == "style")
        self.csp = ("default-src 'none'; script-src " + scripts +
                    "; style-src " + styles + "; connect-src 'self'; img-src data:;"
                    " base-uri 'none'; frame-ancestors 'none'; form-action 'self'")

    def outbox(self):
        return self._outbox


class OperatorHandler(BaseHTTPRequestHandler):
    server_version = "TaskerArmyOperator/1"
    sys_version = ""

    def setup(self):
        super().setup()
        self.connection.settimeout(15)

    def log_message(self, _format, *_args):
        # Request URLs and authorization material never enter access logs.
        pass

    def respond(self, status, payload, content_type="application/json; charset=utf-8"):
        raw = payload if isinstance(payload, bytes) else json.dumps(
            payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Content-Security-Policy", self.server.csp)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(raw)

    def boundary(self, authenticated=True):
        hosts = self.headers.get_all("Host") or []
        if hosts != [urlsplit(self.server.origin).netloc]:
            raise OperatorError(403, "unexpected_host", "Open the printed local console URL")
        origins = self.headers.get_all("Origin") or []
        if origins and origins != [self.server.origin]:
            raise OperatorError(403, "unexpected_origin", "Use the local operator console")
        if authenticated:
            values = self.headers.get_all("Authorization") or []
            wanted = "Bearer " + self.server.token
            if len(values) != 1 or not hmac.compare_digest(values[0], wanted):
                raise OperatorError(401, "authentication_required",
                                    "Open the console link printed by the operator process")

    def body(self):
        if self.headers.get("Transfer-Encoding") is not None:
            raise InputError("Chunked request bodies are not supported")
        lengths = self.headers.get_all("Content-Length") or []
        if len(lengths) != 1:
            raise InputError("Supply one Content-Length")
        length = integer(lengths[0], "Content-Length", maximum=MAX_BODY)
        if self.headers.get("Content-Type", "").split(";")[0].strip() != "application/json":
            raise InputError("Use an application/json request body")
        raw = self.rfile.read(length)
        if len(raw) != length:
            raise InputError("Request body was incomplete")
        result = json.loads(raw.decode("utf-8"))
        if not isinstance(result, dict):
            raise InputError("Request body must be an object")
        return result

    def tenant(self, value, optional=False):
        if optional and not value:
            return None
        value = identifier(value, "tenant_id")
        config = load_config(str(self.server.config))
        if value not in config["tenants"]:
            raise OperatorError(404, "tenant_not_found", "Tenant is not in the current configuration")
        return value

    def dispatch(self):
        parsed = urlsplit(self.path)
        if parsed.scheme or parsed.netloc:
            raise InputError("Use an origin-relative request")
        path, query = parsed.path, parse_qs(parsed.query, keep_blank_values=True)
        if self.command == "GET" and path in ("/", "/healthz"):
            self.boundary(authenticated=False)
            if path == "/":
                return self.respond(200, self.server.html, "text/html; charset=utf-8")
            return self.respond(200, {"service": "taskerarmy-notification-operator", "status": "ready"})
        self.boundary()
        outbox = self.server.outbox()
        if self.command == "GET":
            if path == "/api/config":
                return self.respond(200, public_configuration(self.server.config))
            if path == "/api/status":
                tenant = self.tenant(scalar(query, "tenant_id"), optional=True)
                limit = integer(scalar(query, "limit", "200"), "limit", maximum=1000)
                return self.respond(200, browser_record(outbox.status(tenant, limit=limit)))
            if path.startswith("/api/deliveries/"):
                key = delivery_key(unquote(path.removeprefix("/api/deliveries/")))
                row = safe_delivery(outbox.inspect(key))
                self.tenant(row.get("tenant_id"))
                return self.respond(200, browser_record(row))
            if path == "/api/jobs":
                tenant = self.tenant(scalar(query, "tenant_id"))
                job = identifier(scalar(query, "job_id"), "job_id")
                before = scalar(query, "before_version")
                before = None if before is None else integer(before, "before_version",
                                                               minimum=1, maximum=2**63-1)
                limit = integer(scalar(query, "limit", "50"), "limit", maximum=100)
                return self.respond(200, browser_record(outbox.job_timeline(tenant, job, before_version=before,
                                                                           limit=limit)))
        if self.command == "POST":
            data = self.body()
            if path == "/api/config":
                exact_fields(data, {"expected_revision", "configuration"}, "Configuration request")
                saved = save_configuration(self.server.config, data.get("expected_revision"),
                                           data.get("configuration"))
                return self.respond(200, {"revision": saved, **public_configuration(self.server.config)})
            if path == "/api/resolve":
                exact_fields(data, {"delivery_id", "resolution", "note"}, "Resolution request")
                key = delivery_key(data.get("delivery_id"))
                row = safe_delivery(outbox.inspect(key))
                self.tenant(row.get("tenant_id"))
                note = data.get("note")
                if not isinstance(note, str) or len(note.strip()) < 8 or len(note) > 300:
                    raise InputError("Record a clear resolution note of 8 to 300 characters")
                if data.get("resolution") not in {"sent", "retry", "cancelled"}:
                    raise InputError("Choose sent, retry or cancelled")
                return self.respond(200, browser_record(outbox.resolve(key, data["resolution"], note.strip())))
            if path == "/api/resume-route":
                exact_fields(data, {"route_id"}, "Resume request")
                key = identifier(data.get("route_id"), "route_id")
                config = load_config(str(self.server.config))
                route = next((row for row in config["routes"] if row["id"] == key), None)
                if route is None:
                    raise OperatorError(404, "route_not_found", "Route is not in the current configuration")
                self.tenant(route["tenant_id"])
                return self.respond(200, outbox.resume_route(key))
        raise OperatorError(404, "not_found", "This operator route is not available")

    def handle_request(self):
        try:
            self.dispatch()
        except OperatorError as error:
            self.respond(error.status, {"error": error.code, "message": str(error)})
        except (InputError, ValueError, KeyError, TypeError) as error:
            self.respond(400, {"error": "invalid_request", "message": str(error)[:500]})
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            return
        except Exception:
            self.respond(500, {"error": "operator_error",
                               "message": "The operator could not complete this request. Check its configuration and database."})

    do_GET = handle_request
    do_POST = handle_request

    def do_OPTIONS(self):
        self.respond(405, {"error": "method_not_allowed"})


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--database", required=True, help="The worker's existing SQLite database")
    parser.add_argument("--config", required=True, help="The worker's existing JSON configuration")
    parser.add_argument("--port", type=int, default=8095)
    parser.add_argument("--token-env", default="TASKER_OPERATOR_TOKEN",
                        help="Environment variable holding an optional operator token")
    args = parser.parse_args(argv)
    if not 0 <= args.port <= 65535:
        parser.error("port must be between 0 and 65535")
    database, config = Path(args.database).resolve(), Path(args.config).resolve()
    load_config(str(config))
    token = os.environ.get(args.token_env) or secrets.token_urlsafe(32)
    if len(token) < 32 or not re.fullmatch(r"[A-Za-z0-9_-]+", token):
        parser.error("operator token must be at least 32 URL-safe characters")
    html = Path(__file__).with_name("operator.html").read_bytes()
    server = OperatorServer(args.port, database, config, token, html)
    print("TaskerArmy notification operator is ready on loopback.", flush=True)
    print("Open locally: " + server.origin + "/#token=" + token, flush=True)
    print("The worker continues delivery in its existing process. Ctrl-C closes this console.", flush=True)
    try:
        server.serve_forever(poll_interval=0.5)
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Complete TaskerArmy source and workspace archives.

Uses the maintained TJLabs complete runtime archive implementation.
The reusable source identities are retained in native/PROVENANCE.json.
"""
from __future__ import annotations
import gzip, hashlib, io, json, os, pathlib, posixpath, stat, tarfile, tempfile

SCHEMA = "taskerarmy.handover.archive.v1"
MANIFEST = "TASKER_FILES.json"

def digest_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as stream:
        for body in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(body)
    return h.hexdigest()

def relative_name(value):
    if not isinstance(value, str) or not value or "\\" in value or "\0" in value:
        raise ValueError("An ordinary relative path is required")
    if value.startswith("/") or any(x in ("", ".", "..") for x in value.split("/")):
        raise ValueError("The selected path leaves the package")
    return pathlib.PurePosixPath(value)

def link_target(relative, target):
    relative_name(relative)
    if not isinstance(target, str) or not target or "\\" in target or "\0" in target or target.startswith("/"):
        raise ValueError("A package link must remain relative")
    joined = posixpath.normpath(posixpath.join(posixpath.dirname(relative), target))
    if joined == ".." or joined.startswith("../") or joined.startswith("/"):
        raise ValueError("A package link leaves its original root")
    return joined

def ordinary_parents(root, relative):
    root = pathlib.Path(root)
    if root.is_symlink() or not root.is_dir():
        raise ValueError("The receiving root must be an ordinary directory")
    parts = relative_name(relative).parts
    current = root
    for part in parts[:-1]:
        current = current / part
        if current.is_symlink():
            raise ValueError("An archive member has a linked parent")
        if current.exists():
            if not current.is_dir():
                raise ValueError("An archive member has a non-directory parent")
        else:
            current.mkdir(mode=0o700)
    return root.joinpath(*parts)

def atomic_json(path, value):
    path = pathlib.Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.is_symlink():
        raise ValueError("A runtime record cannot replace a link")
    body = (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode()
    fd, name = tempfile.mkstemp(prefix="." + path.name + "-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(body)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, 0o600)
        os.replace(name, path)
        directory = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        if os.path.exists(name):
            os.unlink(name)

def inventory(root, exclude_root=()):
    root = pathlib.Path(root).resolve(strict=True)
    excluded = set(exclude_root)
    rows = []
    def visit(directory):
        for item in sorted(os.scandir(directory), key=lambda x: x.name):
            path = pathlib.Path(item.path)
            rel = path.relative_to(root).as_posix()
            relative_name(rel)
            if path.parent == root and item.name in excluded:
                continue
            mode = item.stat(follow_symlinks=False).st_mode
            if stat.S_ISLNK(mode):
                target = os.readlink(path)
                link_target(rel, target)
                body = target.encode()
                rows.append({"path": rel, "kind": "symlink", "target": target,
                             "bytes": len(body), "sha256": hashlib.sha256(body).hexdigest(),
                             "mode": 0o777})
            elif stat.S_ISDIR(mode):
                rows.append({"path": rel, "kind": "directory", "mode": 0o700})
                visit(path)
            elif stat.S_ISREG(mode):
                before = item.stat(follow_symlinks=False)
                checksum = digest_file(path)
                after = path.stat()
                if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
                    after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns
                ):
                    raise ValueError("A runtime file changed during export: " + rel)
                rows.append({"path": rel, "kind": "file", "bytes": before.st_size,
                             "sha256": checksum, "mode": 0o700 if mode & 0o111 else 0o600})
            else:
                raise ValueError("A runtime contains an unsupported special file: " + rel)
    visit(root)
    return rows

def write_bundle(root, output, metadata, exclude_root=()):
    root = pathlib.Path(root).resolve(strict=True)
    output = pathlib.Path(output).absolute()
    if output == root or root in output.parents:
        raise ValueError("Write the runtime export outside its source directory")
    if output.exists() or output.is_symlink():
        raise FileExistsError(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    rows = inventory(root, exclude_root)
    if any(x["path"] == MANIFEST for x in rows):
        raise ValueError("The runtime uses the reserved archive manifest name")
    manifest = {"schema": SCHEMA, "metadata": metadata, "files": rows}
    manifest_bytes = (json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode()
    temporary_fd, temporary_name = tempfile.mkstemp(prefix="." + output.name + "-", suffix=".partial", dir=output.parent)
    temporary = pathlib.Path(temporary_name)
    try:
        with os.fdopen(temporary_fd, "wb") as raw:
            with gzip.GzipFile(fileobj=raw, mode="wb", mtime=0) as compressed:
                with tarfile.open(fileobj=compressed, mode="w|", format=tarfile.PAX_FORMAT) as archive:
                    for row in rows:
                        path = root.joinpath(*relative_name(row["path"]).parts)
                        info = tarfile.TarInfo(row["path"])
                        info.mode = row["mode"]
                        info.mtime = 0
                        if row["kind"] == "directory":
                            info.type = tarfile.DIRTYPE
                            archive.addfile(info)
                        elif row["kind"] == "symlink":
                            if not path.is_symlink() or os.readlink(path) != row["target"]:
                                raise ValueError("A runtime link changed during export")
                            info.type = tarfile.SYMTYPE
                            info.linkname = row["target"]
                            archive.addfile(info)
                        else:
                            if path.is_symlink() or path.stat().st_size != row["bytes"]:
                                raise ValueError("A runtime file changed during export")
                            info.size = row["bytes"]
                            class HashingReader:
                                def __init__(self, stream):
                                    self.stream = stream
                                    self.hash = hashlib.sha256()
                                def read(self, size=-1):
                                    part = self.stream.read(size)
                                    self.hash.update(part)
                                    return part
                            fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
                            with os.fdopen(fd, "rb") as stream:
                                body = HashingReader(stream)
                                archive.addfile(info, body)
                            if body.hash.hexdigest() != row["sha256"]:
                                raise ValueError("A runtime file changed during export")
                    info = tarfile.TarInfo(MANIFEST)
                    info.mode = 0o600
                    info.size = len(manifest_bytes)
                    archive.addfile(info, io.BytesIO(manifest_bytes))
            raw.flush()
            os.fsync(raw.fileno())
        os.chmod(temporary, 0o600)
        os.link(temporary, output)
        os.unlink(temporary)
        directory_fd = os.open(output.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except BaseException:
        # A partial export is retained for its original operation to inspect.
        raise
    return {"schema": SCHEMA, "path": str(output), "bytes": output.stat().st_size,
            "sha256": digest_file(output), "manifest_sha256": hashlib.sha256(manifest_bytes).hexdigest(),
            "files": sum(x["kind"] != "directory" for x in rows),
            "uncompressed_bytes": sum(x.get("bytes", 0) for x in rows)}

def checked_manifest(archive):
    members = archive.getmembers()
    by_name = {}
    for item in members:
        name = item.name.rstrip("/") if item.isdir() else item.name
        relative_name(name)
        if name in by_name:
            raise ValueError("The archive repeats an original member: " + name)
        if not (item.isfile() or item.isdir() or item.issym()) or item.islnk():
            raise ValueError("The archive contains an unsupported special member")
        by_name[name] = item
    selected = by_name.get(MANIFEST)
    if not selected or not selected.isfile() or selected.size > 64 * 1024 * 1024:
        raise ValueError("The complete runtime file manifest is missing")
    raw = archive.extractfile(selected).read()
    manifest = json.loads(raw)
    if manifest.get("schema") != SCHEMA or not isinstance(manifest.get("files"), list):
        raise ValueError("The selected archive is not a complete runtime")
    rows = {}
    for row in manifest["files"]:
        name = str(relative_name(row["path"]))
        if name == MANIFEST or name in rows:
            raise ValueError("The runtime file manifest repeats a member")
        if row.get("kind") not in ("file", "directory", "symlink"):
            raise ValueError("The runtime file manifest has an unknown member type")
        if row.get("kind") == "directory":
            if row.get("mode") != 0o700:
                raise ValueError("An archived directory mode differs")
        else:
            if type(row.get("bytes")) is not int or row["bytes"] < 0:
                raise ValueError("An archived member has an invalid byte length")
            checksum = row.get("sha256", "")
            if not isinstance(checksum, str) or len(checksum) != 64 or any(c not in "0123456789abcdef" for c in checksum):
                raise ValueError("An archived member has an invalid content identity")
            if row.get("mode") not in ((0o777,) if row["kind"] == "symlink" else (0o600, 0o700)):
                raise ValueError("An archived member mode differs")
        rows[name] = row
    if set(by_name) != set(rows) | {MANIFEST}:
        raise ValueError("The runtime archive and its original manifest differ")
    for name, row in rows.items():
        item = by_name[name]
        kind = row["kind"]
        if kind == "directory":
            if not item.isdir():
                raise ValueError("A runtime directory has changed type")
        elif kind == "symlink":
            if not item.issym() or item.linkname != row["target"]:
                raise ValueError("A runtime link has changed")
            link_target(name, item.linkname)
            body = item.linkname.encode()
            if len(body) != row["bytes"] or hashlib.sha256(body).hexdigest() != row["sha256"]:
                raise ValueError("The original runtime link bytes differ")
        else:
            if not item.isfile() or item.size != row["bytes"]:
                raise ValueError("An original runtime file has changed size or type")
            h = hashlib.sha256()
            with archive.extractfile(item) as body:
                for part in iter(lambda: body.read(1024 * 1024), b""):
                    h.update(part)
            if h.hexdigest() != row["sha256"]:
                raise ValueError("An original runtime file differs: " + name)
        parent = pathlib.PurePosixPath(name).parent
        while str(parent) != ".":
            if str(parent) in rows and rows[str(parent)]["kind"] != "directory":
                raise ValueError("An archive member has a non-directory parent")
            parent = parent.parent
    return manifest, raw, by_name

def receive_bundle(archive_path, destination, temporary_directory=None):
    archive_path = pathlib.Path(archive_path).resolve(strict=True)
    destination = pathlib.Path(destination).absolute()
    if destination.is_symlink():
        raise ValueError("The receiving directory must be ordinary")
    if temporary_directory is not None:
        temporary_directory = pathlib.Path(temporary_directory).absolute()
        if temporary_directory.is_symlink():
            raise ValueError("The receiving temporary directory must be ordinary")
        temporary_directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    with tarfile.open(archive_path, "r:gz") as archive:
        manifest, manifest_raw, by_name = checked_manifest(archive)
        destination.mkdir(parents=True, exist_ok=True, mode=0o700)
        rows = sorted(manifest["files"], key=lambda x: (x["kind"] == "symlink", x["path"]))
        for row in rows:
            target = ordinary_parents(destination, row["path"])
            if row["kind"] == "directory":
                if target.is_symlink() or (target.exists() and not target.is_dir()):
                    raise ValueError("An existing receiving directory differs")
                target.mkdir(exist_ok=True, mode=0o700)
            elif row["kind"] == "symlink":
                if target.is_symlink():
                    if os.readlink(target) != row["target"]:
                        raise ValueError("An existing receiving link differs")
                elif target.exists():
                    raise ValueError("An existing receiving file differs")
                else:
                    os.symlink(row["target"], target)
            else:
                if target.is_symlink():
                    raise ValueError("An existing receiving file is a link")
                if target.exists():
                    if not target.is_file() or target.stat().st_size != row["bytes"] or digest_file(target) != row["sha256"]:
                        raise ValueError("An existing receiving file differs: " + row["path"])
                    continue
                fd, temporary = tempfile.mkstemp(prefix="." + target.name + "-", dir=temporary_directory or target.parent)
                try:
                    with os.fdopen(fd, "wb") as output, archive.extractfile(by_name[row["path"]]) as source:
                        for part in iter(lambda: source.read(1024 * 1024), b""):
                            output.write(part)
                        output.flush()
                        os.fsync(output.fileno())
                    os.chmod(temporary, row["mode"])
                    if digest_file(temporary) != row["sha256"]:
                        raise ValueError("A copied runtime member differs")
                    try:
                        os.link(temporary, target)
                    except FileExistsError:
                        if target.is_symlink() or not target.is_file() or target.stat().st_size != row["bytes"] or digest_file(target) != row["sha256"]:
                            raise ValueError("A concurrently received file differs")
                    directory_fd = os.open(target.parent, os.O_RDONLY)
                    try:
                        os.fsync(directory_fd)
                    finally:
                        os.close(directory_fd)
                finally:
                    if os.path.exists(temporary):
                        os.unlink(temporary)
    return {"schema": SCHEMA, "directory": str(destination.resolve()), "manifest": manifest,
            "manifest_sha256": hashlib.sha256(manifest_raw).hexdigest(),
            "archive": {"path": str(archive_path), "bytes": archive_path.stat().st_size,
                        "sha256": digest_file(archive_path)}}

#!/usr/bin/env python3
"""Install, snapshot and receive the original TaskerArmy notification application."""
from __future__ import annotations
import argparse, contextlib, datetime as dt, fcntl, hashlib, importlib.util, json, os
import pathlib, shutil, sqlite3, stat, subprocess, sys, time, uuid
from urllib.parse import quote
sys.dont_write_bytecode = True
import archive as package

INSTALL_SCHEMA = "taskerarmy.installation.v1"
SOURCE_SCHEMA = "taskerarmy.application-source.v1"
SNAPSHOT_SCHEMA = "taskerarmy.workspace-snapshot.v1"
RECEIVE_SCHEMA = "taskerarmy.receiving.v1"
_COPY_DIRECTORY = None
REQUIRED_SOURCE = {"notification_outbox.py", "README.md", "operator_server.py", "operator.html", "OPERATOR.md", "native/archive.py", "native/manage.py"}

def utc():
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

def read_json(path):
    return json.loads(pathlib.Path(path).read_text(encoding="utf-8"))

def binding(directory):
    directory = pathlib.Path(directory).resolve(strict=True)
    info = directory.stat()
    return {"directory": str(directory), "device": info.st_dev, "inode": info.st_ino}

def ordinary(path, directory=False):
    path = pathlib.Path(path).absolute()
    if path.is_symlink() or not path.exists() or (not path.is_dir() if directory else not path.is_file()):
        raise ValueError("Select an existing ordinary " + ("directory" if directory else "file") + ": " + str(path))
    return path.resolve(strict=True)

def private_directory(path):
    path = pathlib.Path(path).absolute()
    if path.is_symlink():
        raise ValueError("A selected installation directory cannot be a link")
    path.mkdir(parents=True, exist_ok=True, mode=0o700)
    if not path.is_dir():
        raise ValueError("The selected installation root is not a directory")
    return path.resolve(strict=True)

@contextlib.contextmanager
def locked(root, name=".native.lock"):
    global _COPY_DIRECTORY
    root = private_directory(root)
    prior_copy_directory = _COPY_DIRECTORY
    _COPY_DIRECTORY = root / ".copy-partials"
    path = root / name
    fd = os.open(path, os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield root
    except BlockingIOError as exc:
        raise RuntimeError("The original installation operation still owns this directory") from exc
    finally:
        _COPY_DIRECTORY = prior_copy_directory
        os.close(fd)

def copy_file(source, destination, expected=None):
    source = ordinary(source)
    destination = pathlib.Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if destination.is_symlink():
        raise ValueError("A receiving file cannot replace a link")
    before = source.stat()
    digest = package.digest_file(source)
    if expected is not None and digest != expected:
        raise ValueError("The original selected file changed: " + str(source))
    if destination.exists():
        if not destination.is_file() or destination.stat().st_size != before.st_size or package.digest_file(destination) != digest:
            raise ValueError("A retained receiving file differs: " + str(destination))
        return
    if _COPY_DIRECTORY is None:
        raise RuntimeError("Copy original files inside the selected installation operation")
    temporary_directory = private_directory(_COPY_DIRECTORY)
    temporary = temporary_directory / ("copy-" + uuid.uuid4().hex + ".partial")
    with open(source, "rb") as src, open(temporary, "xb") as out:
        shutil.copyfileobj(src, out, 1024 * 1024)
        out.flush()
        os.fsync(out.fileno())
    os.chmod(temporary, 0o700 if before.st_mode & 0o111 else 0o600)
    after = source.stat()
    if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns) != (
            after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns) or package.digest_file(temporary) != digest:
        raise ValueError("The selected file changed during receiving: " + str(source))
    try:
        os.link(temporary, destination)
    except FileExistsError:
        if destination.is_symlink() or not destination.is_file() or package.digest_file(destination) != digest:
            raise ValueError("A concurrently received original file differs")
    else:
        directory_fd = os.open(destination.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    temporary.unlink()

def copy_directory(source, destination, allowed_extra_roots=()):
    source = ordinary(source, True)
    destination = private_directory(destination)
    rows = package.inventory(source)
    for row in sorted(rows, key=lambda item: (item["kind"] == "symlink", item["path"])):
        target = package.ordinary_parents(destination, row["path"])
        if row["kind"] == "directory":
            if target.is_symlink() or (target.exists() and not target.is_dir()):
                raise ValueError("A selected directory changed type")
            target.mkdir(exist_ok=True, mode=0o700)
        elif row["kind"] == "symlink":
            if target.is_symlink():
                if os.readlink(target) != row["target"]:
                    raise ValueError("A received link differs")
            elif target.exists():
                raise ValueError("A received link has an existing ordinary file")
            else:
                os.symlink(row["target"], target)
        else:
            copy_file(source / row["path"], target, row["sha256"])
    received = {row["path"]: row for row in package.inventory(destination)}
    expected = {row["path"]: row for row in rows}
    if any(received.get(name) != row for name, row in expected.items()):
        raise ValueError("Complete directory receiving differs from its original selection")
    permitted = set(allowed_extra_roots)
    if any(name.split("/", 1)[0] in permitted for name in expected):
        raise ValueError("A current receiving lineage repeats an original prior lineage identity")
    if any(name not in expected and name.split("/", 1)[0] not in permitted for name in received):
        raise ValueError("Complete directory receiving contains an unrelated additional member")
    return rows

def source_manifest(application, manifest_path=None):
    application = ordinary(application, True)
    manifest = read_json(manifest_path) if manifest_path else None
    rows = [row for row in package.inventory(application, exclude_root=("SOURCE_FILES.json", ".git"))
            if row["kind"] != "directory"]
    if any(row["kind"] != "file" for row in rows):
        raise ValueError("The selected Python application source must contain ordinary files")
    by_path = {row["path"]: row for row in rows}
    if not REQUIRED_SOURCE.issubset(by_path):
        raise ValueError("The complete original worker and native source are required")
    if manifest is None:
        manifest = {"schema": SOURCE_SCHEMA, "files": [
            {key: row[key] for key in ("path", "bytes", "sha256", "mode")} for row in rows]}
    if manifest.get("schema") != SOURCE_SCHEMA or not isinstance(manifest.get("files"), list):
        raise ValueError("Select the complete TaskerArmy application source manifest")
    declared = {}
    for row in manifest["files"]:
        name = str(package.relative_name(row["path"]))
        if name in declared or type(row.get("bytes")) is not int or row["bytes"] < 0:
            raise ValueError("Invalid or repeated application source member")
        actual = by_path.get(name)
        if not actual or row["bytes"] != actual["bytes"] or row.get("sha256") != actual["sha256"]:
            raise ValueError("The selected source manifest differs: " + name)
        declared[name] = row
    if set(declared) != set(by_path):
        raise ValueError("The complete source selection and original manifest differ")
    return manifest

def copy_selected_source(application, destination, manifest):
    destination = private_directory(destination)
    for row in manifest["files"]:
        copy_file(pathlib.Path(application) / row["path"],
                  package.ordinary_parents(destination, row["path"]), row["sha256"])
    # Validate the complete copy, not just the files named by the caller.
    current = source_manifest(destination)
    if {r["path"]: (r["sha256"], r["bytes"]) for r in current["files"]} != {
            r["path"]: (r["sha256"], r["bytes"]) for r in manifest["files"]}:
        raise ValueError("Complete installed source differs")
    return destination

def worker_module(application):
    filename = ordinary(pathlib.Path(application) / "notification_outbox.py")
    name = "taskerarmy_original_" + hashlib.sha256(str(filename).encode()).hexdigest()[:20]
    spec = importlib.util.spec_from_file_location(name, filename)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def python_identity(executable):
    executable = ordinary(pathlib.Path(executable).resolve(strict=True))
    command = [str(executable), "-c", "import json,sys;print(json.dumps({'version':list(sys.version_info[:3]),'executable':sys.executable}))"]
    result = subprocess.run(command, text=True, capture_output=True, check=True, timeout=20)
    value = json.loads(result.stdout)
    if tuple(value["version"][:2]) < (3, 11):
        raise ValueError("TaskerArmy requires Python 3.11 or later")
    return {"path": str(executable), "version": value["version"]}

def source_locations(root, value):
    root = pathlib.Path(root)
    edition = value.get("source_edition")
    if edition is not None and (not isinstance(edition, str) or len(edition) != 64
                               or any(c not in "0123456789abcdef" for c in edition)):
        raise ValueError("The selected source edition identity is invalid")
    selected = root / "source-editions" / edition if edition is not None else root
    return {"original": selected / "original-source", "application": selected / "application",
            "manifest": selected / "source-manifest.json"}

def installation(directory):
    root = ordinary(directory, True)
    value = read_json(root / "installation.json")
    if value.get("schema") != INSTALL_SCHEMA or value.get("binding") != binding(root):
        raise ValueError("The selected installation identity or directory changed")
    selected = source_locations(root, value)
    expected = {"directory": str(root), "application": str(selected["application"]),
                "configuration": str(root / "state" / "notices.json"),
                "database": str(root / "state" / "notices.sqlite3")}
    if value.get("paths") != expected:
        raise ValueError("The selected installation paths differ from their original binding")
    for key in ("application",):
        ordinary(value["paths"][key], True)
    for key in ("configuration", "database"):
        ordinary(value["paths"][key])
    return value

def outbox_for(value):
    module = worker_module(value["paths"]["application"])
    return module, module.Outbox(value["paths"]["database"], value["paths"]["configuration"])

def prepare(application, configuration, directory, manifest_path=None, python=None, operation_id=None):
    application = ordinary(application, True)
    configuration = ordinary(configuration)
    manifest = source_manifest(application, manifest_path)
    source_id = hashlib.sha256(canonical(manifest).encode()).hexdigest()
    config_hash = package.digest_file(configuration)
    selected_python = python_identity(python or sys.executable)
    module = worker_module(application)
    module.load_config(configuration)
    request = {"schema": "taskerarmy.installation-request.v1",
               "source_identity": source_id, "configuration_sha256": config_hash,
               "python": selected_python, "operation_id": operation_id or "taskerarmy-installation"}
    root = pathlib.Path(directory).absolute()
    if root == application or application in root.parents or root in application.parents:
        raise ValueError("Select a separate private installation directory")
    with locked(root):
        request_path = root / "prepare-request.json"
        if request_path.exists():
            if read_json(request_path) != request:
                raise ValueError("This installation directory belongs to another original selection")
        else:
            existing = [p.name for p in root.iterdir() if p.name != ".native.lock"]
            if existing:
                raise ValueError("The first installation requires a new selected directory")
            package.atomic_json(request_path, request)
        if (root / "installation.json").exists():
            existing = installation(root)
            if existing["source_identity"] != source_id:
                raise ValueError("The completed installation has another source selection")
            return {**existing, "replayed": True}
        copy_selected_source(application, root / "original-source", manifest)
        copy_selected_source(application, root / "application", manifest)
        copy_file(configuration, root / "state" / "notices.json", config_hash)
        module = worker_module(root / "application")
        outbox = module.Outbox(root / "state" / "notices.sqlite3", root / "state" / "notices.json")
        summary = database_summary(outbox.database)
        package.atomic_json(root / "source-manifest.json", manifest)
        value = {"schema": INSTALL_SCHEMA, "installation_id": str(uuid.uuid4()), "created_at": utc(),
                 "operation_id": request["operation_id"], "binding": binding(root),
                 "source_identity": source_id, "python": selected_python,
                 "paths": {"directory": str(root), "application": str(root / "application"),
                           "configuration": str(root / "state" / "notices.json"),
                           "database": str(root / "state" / "notices.sqlite3")},
                 "lineage": [], "initial_database": summary}
        package.atomic_json(root / "installation.json", value)
        return value

def adopt_source(directory, application, manifest_path=None, operation_id=None):
    if not isinstance(operation_id, str) or not operation_id.strip():
        raise ValueError("Select the original source-adoption operation ID")
    application = ordinary(application, True)
    manifest = source_manifest(application, manifest_path)
    source_id = hashlib.sha256(canonical(manifest).encode()).hexdigest()
    adoption_id = hashlib.sha256(canonical({"operation_id": operation_id, "source_identity": source_id}).encode()).hexdigest()
    with locked(directory) as root:
        current = installation(root)
        working = root / "source-adoptions" / adoption_id
        working.mkdir(parents=True, exist_ok=True, mode=0o700)
        request_path = working / "request.json"
        if request_path.exists():
            request = read_json(request_path)
            if (request.get("schema") != "taskerarmy.source-adoption-request.v1"
                    or request["operation_id"] != operation_id or request["source_identity"] != source_id
                    or request["application"] != str(application)
                    or request["installation_id"] != current["installation_id"]
                    or request["prior_installation"]["binding"] != binding(root)):
                raise ValueError("The retained source adoption belongs to another original selection")
        else:
            request = {"schema": "taskerarmy.source-adoption-request.v1", "operation_id": operation_id,
                       "adoption_id": adoption_id, "created_at": utc(), "application": str(application),
                       "source_identity": source_id, "installation_id": current["installation_id"],
                       "prior_installation": current}
            package.atomic_json(request_path, request)
        previous = request["prior_installation"]
        prior_paths = source_locations(root, previous)
        edition = root / "source-editions" / adoption_id
        updated = json.loads(canonical(previous))
        updated["source_identity"] = source_id
        updated["source_edition"] = adoption_id
        updated["paths"]["application"] = str(edition / "application")
        updated["lineage"] = list(previous.get("lineage", [])) + [{
            "source_adoption_id": adoption_id, "operation_id": operation_id,
            "created_at": request["created_at"], "previous_source_identity": previous["source_identity"],
            "source_identity": source_id}]
        if current != previous and current != updated:
            raise ValueError("Another source edition was selected after this original adoption")
        result_path = working / "result.json"
        if result_path.exists():
            result = read_json(result_path)
            if result.get("installation") != updated or current != updated:
                raise ValueError("This completed source adoption is no longer the selected installation")
            return {**result, "replayed": True}
        if current == previous:
            prior_manifest = read_json(prior_paths["manifest"])
            source_manifest(prior_paths["original"], prior_paths["manifest"])
            if hashlib.sha256(canonical(prior_manifest).encode()).hexdigest() != previous["source_identity"]:
                raise ValueError("The previous original source edition differs")
            retained = root / "lineage" / "source-adoptions" / adoption_id
            copy_directory(prior_paths["original"], retained / "original-source")
            copy_directory(prior_paths["application"], retained / "application")
            copy_file(prior_paths["manifest"], retained / "source-manifest.json")
            package.atomic_json(retained / "installation.json", previous)
            package.atomic_json(retained / "adoption-request.json", request)
        manifest_path = edition / "source-manifest.json"
        if current == previous:
            copy_selected_source(application, edition / "original-source", manifest)
            copy_selected_source(application, edition / "application", manifest)
            if manifest_path.exists() and read_json(manifest_path) != manifest:
                raise ValueError("The retained successor source manifest differs")
            package.atomic_json(manifest_path, manifest)
        elif source_manifest(edition / "original-source", manifest_path) != manifest:
            raise ValueError("The completed successor original source differs")
        # The original routing and SQLite paths/bytes are never rewritten by source adoption.
        # All prior and successor source files are complete before the selected pointer changes.
        if installation(root) not in (previous, updated):
            raise ValueError("The selected installation changed during source receiving")
        package.atomic_json(root / "installation.json", updated)
        result = {"schema": "taskerarmy.source-adoption-result.v1", "adoption_id": adoption_id,
                  "operation_id": operation_id, "installation": updated,
                  "previous_source_identity": previous["source_identity"],
                  "retained_previous_source": str(root / "lineage" / "source-adoptions" / adoption_id)}
        package.atomic_json(result_path, result)
        return result

def db_connection(path, readonly=True):
    path = ordinary(path)
    if readonly:
        connection = sqlite3.connect("file:" + quote(str(path)) + "?mode=ro", uri=True, timeout=10)
    else:
        connection = sqlite3.connect(path, timeout=10, isolation_level=None)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA busy_timeout=10000")
    return connection

def sql_identifier(value):
    return '"' + value.replace('"', '""') + '"'

def database_summary(path):
    with contextlib.closing(db_connection(path)) as db:
        db.execute("BEGIN")
        integrity = [row[0] for row in db.execute("PRAGMA integrity_check")]
        if integrity != ["ok"]:
            raise ValueError("The retained SQLite workspace is not readable: " + repr(integrity))
        schema = [dict(row) for row in db.execute(
            "SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name")]
        table_names = [row["name"] for row in schema if row["type"] == "table"]
        required = {"schema_version", "events", "jobs", "deliveries", "channels", "route_failures"}
        if not required.issubset(table_names):
            raise ValueError("The original notification tables are incomplete")
        versions = [r[0] for r in db.execute("SELECT version FROM schema_version")]
        if versions != [1]:
            raise ValueError("Unsupported original Outbox database version")
        tables = []
        for name in table_names:
            columns = [r[1] for r in db.execute("PRAGMA table_info(" + sql_identifier(name) + ")")]
            order = ",".join(sql_identifier(c) for c in columns)
            h = hashlib.sha256()
            count = 0
            for row in db.execute("SELECT * FROM " + sql_identifier(name) + " ORDER BY " + order):
                values = [({"bytes_base64": __import__("base64").b64encode(v).decode()} if isinstance(v, bytes) else v)
                          for v in row]
                body = canonical(values).encode()
                h.update(str(len(body)).encode() + b":" + body)
                count += 1
            tables.append({"name": name, "columns": columns, "rows": count, "sha256": h.hexdigest()})
        for row in db.execute("SELECT event_id,payload_hash,event_json FROM events"):
            if hashlib.sha256(row["event_json"].encode()).hexdigest() != row["payload_hash"]:
                raise ValueError("An original retained event body differs: " + row["event_id"])
            json.loads(row["event_json"])
        for row in db.execute("SELECT id,event_json,message_json,message_sha256 FROM deliveries"):
            if hashlib.sha256(row["message_json"].encode()).hexdigest() != row["message_sha256"]:
                raise ValueError("An original retained Slack message differs: " + str(row["id"]))
            json.loads(row["event_json"])
            json.loads(row["message_json"])
        if db.execute("""SELECT COUNT(*) FROM deliveries d LEFT JOIN events e
            ON e.tenant_id=d.tenant_id AND e.event_id=d.event_id
            WHERE e.event_id IS NULL OR e.event_json<>d.event_json
            OR e.job_id<>d.job_id OR e.version<>d.version""").fetchone()[0]:
            raise ValueError("A retained delivery differs from its original event")
        if db.execute("""SELECT COUNT(*) FROM jobs j LEFT JOIN events e
            ON e.tenant_id=j.tenant_id AND e.event_id=j.event_id
            WHERE e.event_id IS NULL OR e.job_id<>j.job_id OR e.version<>j.version""").fetchone()[0]:
            raise ValueError("A retained job differs from its current original event")
        db.rollback()
    return {"schema_sha256": hashlib.sha256(canonical(schema).encode()).hexdigest(),
            "tables": tables, "integrity": "ok"}

def backup_database(source, destination):
    source = ordinary(source)
    destination = pathlib.Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if destination.exists() or destination.is_symlink():
        raise FileExistsError(destination)
    with contextlib.closing(db_connection(source)) as original, \
            contextlib.closing(sqlite3.connect(destination)) as target:
        original.backup(target, pages=256, sleep=0.02)
        target.execute("PRAGMA journal_mode=DELETE")
        target.commit()
    os.chmod(destination, 0o600)
    with open(destination, "rb") as stream:
        os.fsync(stream.fileno())
    return database_summary(destination)

def inspect(directory):
    value = installation(directory)
    module, outbox = outbox_for(value)
    paths = source_locations(pathlib.Path(value["paths"]["directory"]), value)
    manifest = read_json(paths["manifest"])
    selected = source_manifest(paths["original"])
    if hashlib.sha256(canonical(manifest).encode()).hexdigest() != value["source_identity"]:
        raise ValueError("The selected original source manifest identity changed")
    if {r["path"]: (r["sha256"], r["bytes"]) for r in selected["files"]} != {
            r["path"]: (r["sha256"], r["bytes"]) for r in manifest["files"]}:
        raise ValueError("The complete original installed source changed")
    return {"schema": "taskerarmy.installation-inspection.v1", "installation": value,
            "configuration": module.load_config(value["paths"]["configuration"]),
            "configuration_sha256": package.digest_file(value["paths"]["configuration"]),
            "application_files": package.inventory(value["paths"]["application"]),
            "database": database_summary(outbox.database), "outbox": outbox.status(limit=1000)}

def receive_published_snapshot(output, operation_id, installation_id):
    output = ordinary(output)
    with __import__("tarfile").open(output, "r:gz") as stream:
        manifest, raw, members = package.checked_manifest(stream)
        snapshot = json.load(stream.extractfile(members["snapshot.json"]))
        original = json.load(stream.extractfile(members["installation.json"]))
        source = json.load(stream.extractfile(members["source-manifest.json"]))
        source_bytes = stream.extractfile(members["source-manifest.json"]).read()
    meta = manifest.get("metadata", {})
    if (snapshot.get("schema") != SNAPSHOT_SCHEMA or snapshot.get("operation_id") != operation_id
            or snapshot.get("installation_id") != installation_id
            or original != snapshot.get("original_installation")
            or original.get("installation_id") != installation_id
            or original.get("source_identity") != snapshot.get("source_identity")
            or meta.get("snapshot_id") != snapshot.get("snapshot_id")
            or meta.get("operation_id") != operation_id
            or meta.get("installation_id") != installation_id
            or meta.get("source_identity") != snapshot.get("source_identity")):
        raise ValueError("The existing output belongs to another original snapshot, installation or source")
    if (source.get("schema") != SOURCE_SCHEMA
            or hashlib.sha256(source_bytes).hexdigest() != snapshot["source_manifest_sha256"]
            or hashlib.sha256(canonical(source).encode()).hexdigest() != snapshot["source_identity"]):
        raise ValueError("The existing handover has another complete source identity")
    expected = {row["path"]: (row["bytes"], row["sha256"]) for row in source["files"]}
    actual = {row["path"].removeprefix("original-source/"): (row["bytes"], row["sha256"])
              for row in manifest["files"]
              if row["kind"] == "file" and row["path"].startswith("original-source/")}
    if actual != expected:
        raise ValueError("The existing handover does not carry its complete original source")
    configuration = next((row for row in manifest["files"] if row["path"] == "state/notices.json"), None)
    if not configuration or configuration["sha256"] != snapshot["configuration_sha256"]:
        raise ValueError("The existing handover has another routing source")
    archived = {"schema": package.SCHEMA, "path": str(output), "bytes": output.stat().st_size,
                "sha256": package.digest_file(output), "manifest_sha256": hashlib.sha256(raw).hexdigest(),
                "files": sum(row["kind"] != "directory" for row in manifest["files"]),
                "uncompressed_bytes": sum(row.get("bytes", 0) for row in manifest["files"])}
    return {"schema": "taskerarmy.snapshot-result.v1", "snapshot": snapshot, "archive": archived,
            "attempt": None, "recovered_original_output": True}

def snapshot(directory, output, operation_id):
    root = ordinary(directory, True)
    output = pathlib.Path(output).absolute()
    if output == root or root in output.parents:
        raise ValueError("Write the handover archive outside the active installation")
    operation_name = hashlib.sha256(operation_id.encode()).hexdigest()
    with locked(root):
        value = installation(root)
        working = root / "snapshots" / operation_name
        working.mkdir(parents=True, exist_ok=True, mode=0o700)
        request = {"schema": "taskerarmy.snapshot-request.v1",
                   "operation_id": operation_id, "installation_id": value["installation_id"],
                   "output": str(output)}
        request_path = working / "request.json"
        if request_path.exists() and read_json(request_path) != request:
            raise ValueError("This snapshot operation belongs to another original request")
        if not request_path.exists():
            package.atomic_json(request_path, request)
        if (working / "result.json").exists():
            prior = read_json(working / "result.json")
            if ordinary(prior["archive"]["path"]).stat().st_size != prior["archive"]["bytes"] or \
                    package.digest_file(prior["archive"]["path"]) != prior["archive"]["sha256"]:
                raise ValueError("The completed original handover archive differs")
            return {**prior, "replayed": True}
        if output.exists() or output.is_symlink():
            result = receive_published_snapshot(output, operation_id, value["installation_id"])
            package.atomic_json(working / "result.json", result)
            return result
        attempts = working / "attempts"
        attempts.mkdir(exist_ok=True, mode=0o700)
        number = 1
        while (attempts / str(number)).exists():
            number += 1
        attempt = attempts / str(number)
        attempt.mkdir(mode=0o700)
        payload = attempt / "payload"
        payload.mkdir(mode=0o700)
        config_hash = package.digest_file(value["paths"]["configuration"])
        module = worker_module(value["paths"]["application"])
        module.load_config(value["paths"]["configuration"])
        # Original-source validation is independent from the customer's editable application.
        selected = source_locations(root, value)
        original_manifest = read_json(selected["manifest"])
        current_original = source_manifest(selected["original"])
        if hashlib.sha256(canonical(original_manifest).encode()).hexdigest() != value["source_identity"]:
            raise ValueError("The selected original source manifest identity changed")
        if {r["path"]: (r["sha256"], r["bytes"]) for r in original_manifest["files"]} != {
                r["path"]: (r["sha256"], r["bytes"]) for r in current_original["files"]}:
            raise ValueError("The original application source baseline changed")
        copy_directory(selected["original"], payload / "original-source")
        copy_directory(selected["application"], payload / "application")
        copy_file(selected["manifest"], payload / "source-manifest.json")
        copy_file(root / "installation.json", payload / "installation.json")
        copy_file(value["paths"]["configuration"], payload / "state" / "notices.json", config_hash)
        database = backup_database(value["paths"]["database"], payload / "state" / "notices.sqlite3")
        if config_hash != package.digest_file(value["paths"]["configuration"]):
            raise ValueError("Routing changed during the selected snapshot; the original attempt is retained")
        if (root / "lineage").exists():
            copy_directory(root / "lineage", payload / "lineage")
        original_configuration = module.load_config(payload / "state" / "notices.json")
        captured = {"schema": SNAPSHOT_SCHEMA, "snapshot_id": str(uuid.uuid4()),
                    "operation_id": operation_id, "created_at": utc(),
                    "installation_id": value["installation_id"], "source_identity": value["source_identity"],
                    "original_installation": value, "configuration_sha256": config_hash,
                    "configuration": original_configuration, "database": database,
                    "source_manifest_sha256": package.digest_file(payload / "source-manifest.json")}
        package.atomic_json(payload / "snapshot.json", captured)
        archive_result = package.write_bundle(payload, output,
            {"operation_id": operation_id, "installation_id": value["installation_id"],
             "snapshot_id": captured["snapshot_id"], "source_identity": value["source_identity"]})
        result = {"schema": "taskerarmy.snapshot-result.v1", "snapshot": captured,
                  "archive": archive_result, "attempt": number}
        package.atomic_json(working / "result.json", result)
        return result

def receive(archive_path, directory, python=None):
    archive_path = ordinary(archive_path)
    checksum = package.digest_file(archive_path)
    selected_python = python_identity(python or sys.executable)
    root = pathlib.Path(directory).absolute()
    with locked(root, ".receive.lock"):
        request_path = root / "receiving-request.json"
        request = {"schema": "taskerarmy.receiving-request.v1", "archive_sha256": checksum,
                   "archive_bytes": archive_path.stat().st_size, "python": selected_python}
        if request_path.exists():
            if read_json(request_path) != request:
                raise ValueError("This receiving directory belongs to another original archive or Python selection")
        else:
            existing = [p.name for p in root.iterdir() if p.name != ".receive.lock"]
            if existing:
                raise ValueError("The first receiving requires a new private directory")
            package.atomic_json(request_path, request)
        if (root / "receiving.json").exists():
            existing = read_json(root / "receiving.json")
            current = installation(existing["installation"]["paths"]["directory"])
            if current["installation_id"] != existing["installation"]["installation_id"]:
                raise ValueError("The original received installation identity changed")
            return {**existing, "replayed": True}
        received = package.receive_bundle(archive_path, root / "payload", root / ".receiving-temporary")
        payload = root / "payload"
        snap = read_json(payload / "snapshot.json")
        if snap.get("schema") != SNAPSHOT_SCHEMA:
            raise ValueError("This archive is not a TaskerArmy workspace handover")
        previous = read_json(payload / "installation.json")
        meta = received["manifest"].get("metadata", {})
        if (snap["installation_id"] != previous.get("installation_id")
                or snap["source_identity"] != previous.get("source_identity")
                or snap["original_installation"] != previous
                or meta.get("snapshot_id") != snap["snapshot_id"]
                or meta.get("operation_id") != snap["operation_id"]
                or meta.get("installation_id") != snap["installation_id"]
                or meta.get("source_identity") != snap["source_identity"]):
            raise ValueError("The original installation, snapshot and source lineage differ")
        source_manifest_path = payload / "source-manifest.json"
        if package.digest_file(source_manifest_path) != snap["source_manifest_sha256"]:
            raise ValueError("The original complete source manifest differs")
        manifest = source_manifest(payload / "original-source", source_manifest_path)
        if hashlib.sha256(canonical(manifest).encode()).hexdigest() != snap["source_identity"]:
            raise ValueError("The original source identity differs")
        if package.digest_file(payload / "state" / "notices.json") != snap["configuration_sha256"]:
            raise ValueError("The original routing bytes differ")
        module = worker_module(payload / "application")
        if module.load_config(payload / "state" / "notices.json") != snap["configuration"]:
            raise ValueError("The original routing configuration differs")
        if database_summary(payload / "state" / "notices.sqlite3") != snap["database"]:
            raise ValueError("The complete original database tables differ")
        runtime = private_directory(root / "installation")
        copy_directory(payload / "original-source", runtime / "original-source")
        copy_directory(payload / "application", runtime / "application")
        copy_file(source_manifest_path, runtime / "source-manifest.json")
        copy_file(payload / "state" / "notices.json", runtime / "state" / "notices.json")
        preparation_path = root / "receiving-preparation.json"
        if preparation_path.exists():
            preparation = read_json(preparation_path)
        else:
            preparation = {"receiving_id": str(uuid.uuid4()), "installation_id": str(uuid.uuid4()),
                           "created_at": utc(), "archive_sha256": checksum}
            package.atomic_json(preparation_path, preparation)
        if preparation["archive_sha256"] != checksum:
            raise ValueError("The retained receiving preparation names another original archive")
        # Earlier completed lineage and this receiving's retained partial lineage coexist.
        if (payload / "lineage").exists():
            copy_directory(payload / "lineage", runtime / "lineage",
                           allowed_extra_roots=(preparation["receiving_id"],))
        database = runtime / "state" / "notices.sqlite3"
        if not database.exists():
            copy_file(payload / "state" / "notices.sqlite3", database)
        lineage = runtime / "lineage" / preparation["receiving_id"]
        lineage.mkdir(parents=True, exist_ok=True, mode=0o700)
        copy_file(payload / "snapshot.json", lineage / "original-snapshot.json")
        package.atomic_json(lineage / "original-archive-manifest.json", received["manifest"])
        # A lease belongs to the original host. Preserve it in the original payload and
        # receive the same delivery as uncertain in the new workspace, without a transmit.
        recovery_path = lineage / "dispatch-receiving.json"
        if recovery_path.exists():
            recovery = read_json(recovery_path)
        else:
            with contextlib.closing(db_connection(database, readonly=False)) as db:
                db.execute("BEGIN IMMEDIATE")
                dispatched = [dict(row) for row in db.execute(
                    "SELECT id,status,lease_token,lease_until,last_error,updated_at FROM deliveries WHERE status='dispatching'")]
                # Journal the exact original rows before changing the copied workspace.
                recovery = {"schema": "taskerarmy.dispatch-receiving.v1",
                            "at": utc(), "original_installation_id": previous["installation_id"],
                            "received_installation_id": preparation["installation_id"],
                            "deliveries": dispatched}
                package.atomic_json(recovery_path, recovery)
                db.execute("""UPDATE deliveries SET status='uncertain',last_error='installation_received',
                    lease_token=NULL,lease_until=NULL,updated_at=? WHERE status='dispatching'""", (time.time(),))
                db.commit()
        # A result-journal write may precede the SQLite commit. Finish only those same rows.
        with contextlib.closing(db_connection(database, readonly=False)) as db:
            db.execute("BEGIN IMMEDIATE")
            for row in recovery["deliveries"]:
                current = db.execute("SELECT status,lease_token FROM deliveries WHERE id=?", (row["id"],)).fetchone()
                if not current:
                    raise ValueError("An original dispatch row disappeared during receiving")
                if current["status"] == "dispatching" and current["lease_token"] == row["lease_token"]:
                    db.execute("""UPDATE deliveries SET status='uncertain',last_error='installation_received',
                        lease_token=NULL,lease_until=NULL,updated_at=? WHERE id=?""", (time.time(), row["id"]))
                elif current["status"] != "uncertain":
                    raise ValueError("The partially received delivery changed before receiving completed")
            db.commit()
        value = {"schema": INSTALL_SCHEMA, "installation_id": preparation["installation_id"],
                 "created_at": preparation["created_at"], "operation_id": previous["operation_id"],
                 "binding": binding(runtime), "source_identity": previous["source_identity"],
                 "python": selected_python,
                 "paths": {"directory": str(runtime), "application": str(runtime / "application"),
                           "configuration": str(runtime / "state" / "notices.json"), "database": str(database)},
                 "lineage": list(previous.get("lineage", [])) + [{
                     "receiving_id": preparation["receiving_id"], "archive_sha256": checksum,
                     "snapshot_id": snap["snapshot_id"], "original_installation_id": previous["installation_id"]}],
                 "initial_database": database_summary(database)}
        package.atomic_json(runtime / "installation.json", value)
        result = {"schema": RECEIVE_SCHEMA, "receiving_id": preparation["receiving_id"],
                  "received_at": preparation["created_at"], "archive": received["archive"],
                  "manifest_sha256": received["manifest_sha256"],
                  "original_payload": str(payload), "original_snapshot": snap,
                  "installation": value, "recovered_dispatches": [r["id"] for r in recovery["deliveries"]]}
        package.atomic_json(root / "receiving.json", result)
        return result

def command(directory, arguments):
    value = installation(directory)
    if not arguments:
        raise ValueError("Select an original worker command")
    module = worker_module(value["paths"]["application"])
    # Validate routing before the selected original CLI owns any operation.
    module.load_config(value["paths"]["configuration"])
    argv = [value["python"]["path"], "-B", str(pathlib.Path(value["paths"]["application"]) / "notification_outbox.py"),
            "--db", value["paths"]["database"], "--config", value["paths"]["configuration"], *arguments]
    return subprocess.call(argv, cwd=value["paths"]["application"], env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})

def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("manifest")
    p.add_argument("--application", required=True)
    p.add_argument("--output", required=True)
    p = sub.add_parser("prepare")
    p.add_argument("--application", required=True)
    p.add_argument("--configuration", required=True)
    p.add_argument("--directory", required=True)
    p.add_argument("--source-manifest")
    p.add_argument("--python", default=sys.executable)
    p.add_argument("--operation-id")
    p = sub.add_parser("adopt-source")
    p.add_argument("--directory", required=True)
    p.add_argument("--application", required=True)
    p.add_argument("--source-manifest")
    p.add_argument("--operation-id", required=True)
    p = sub.add_parser("inspect")
    p.add_argument("--directory", required=True)
    p = sub.add_parser("export")
    p.add_argument("--directory", required=True)
    p.add_argument("--output", required=True)
    p.add_argument("--operation-id", required=True)
    p = sub.add_parser("receive")
    p.add_argument("--archive", required=True)
    p.add_argument("--directory", required=True)
    p.add_argument("--python", default=sys.executable)
    p = sub.add_parser("run")
    p.add_argument("--directory", required=True)
    p.add_argument("arguments", nargs=argparse.REMAINDER)
    args = parser.parse_args(argv)
    if args.command == "manifest":
        result = source_manifest(args.application)
        output = pathlib.Path(args.output)
        if output.exists():
            if read_json(output) != result:
                raise ValueError("The selected manifest output already contains another source edition")
        else:
            package.atomic_json(output, result)
    elif args.command == "prepare":
        result = prepare(args.application, args.configuration, args.directory, args.source_manifest,
                         args.python, args.operation_id)
    elif args.command == "adopt-source":
        result = adopt_source(args.directory, args.application, args.source_manifest, args.operation_id)
    elif args.command == "inspect":
        result = inspect(args.directory)
    elif args.command == "export":
        result = snapshot(args.directory, args.output, args.operation_id)
    elif args.command == "receive":
        result = receive(args.archive, args.directory, args.python)
    else:
        arguments = args.arguments[1:] if args.arguments[:1] == ["--"] else args.arguments
        return command(args.directory, arguments)
    print(json.dumps(result, ensure_ascii=False, indent=2), flush=True)
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ValueError, OSError, sqlite3.Error, subprocess.SubprocessError) as exc:
        print(json.dumps({"error": type(exc).__name__, "detail": str(exc)}), file=sys.stderr, flush=True)
        raise SystemExit(2)

#!/usr/bin/env python3
"""JSON/CLI operations for the installed TaskerArmy notification application.

The original Outbox and operator configuration writer own business changes.
Named request results live in that same SQLite database and travel through its
original complete SQLite backup and independent receiving implementation.
"""
from __future__ import annotations

import argparse
import contextlib
import hashlib
import importlib.util
import json
import os
import pathlib
import re
import sqlite3
import sys
import tempfile
import time

sys.dont_write_bytecode = True
import manage
import archive as package

REQUEST_SCHEMA = "taskerarmy.operation-request.v1"
RESULT_SCHEMA = "taskerarmy.operation-result.v1"
MAX_REQUEST = 2 * 1024 * 1024
JOURNAL = "taskerarmy_operation_requests"
REQUEST_ID = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}$")
SHA256 = re.compile(r"^[0-9a-f]{64}$")
JSON_SAFE_INTEGER = 2**53 - 1
SOURCE = pathlib.Path(__file__).resolve()
ADAPTER_SHA256 = hashlib.sha256(SOURCE.read_bytes()).hexdigest()
ARGUMENTS = {
    "installation.prepare": {"application", "configuration", "directory", "manifest_path", "python", "operation_id"},
    "installation.inspect": set(),
    "installation.adopt_source": {"application", "manifest_path", "operation_id"},
    "installation.snapshot": {"output", "operation_id"},
    "installation.receive": {"archive_path", "directory", "python"},
    "configuration.read": set(),
    "configuration.save": {"revision", "configuration"},
    "queue.status": {"tenant", "limit"},
    "queue.list": {"tenant", "status", "route_id", "job_id", "before_id", "limit"},
    "queue.get": {"delivery_id"},
    "jobs.history": {"tenant", "job", "before_version", "limit"},
    "events.receive": {"tenant", "event", "ttl_seconds"},
    "events.render": {"tenant", "event"},
    "deliveries.resolve": {"delivery_id", "outcome", "note"},
    "routes.resume": {"route_id"},
    "requests.get": {"request_id", "installation_id"},
    "commands.describe": {"roles", "operator_port", "ingress_port", "worker_interval", "ready_file", "operator_token_env"},
}
NAMED_MUTATIONS = {"configuration.save", "events.receive", "deliveries.resolve", "routes.resume"}
QUEUE_FIELDS = (
    "id", "tenant_id", "route_id", "event_id", "job_id", "version",
    "channel_key", "message_sha256", "status", "attempts", "due_at",
    "expires_at", "created_at", "updated_at", "http_status", "last_error",
    "sent_at", "resolution",
)
JOURNAL_COLUMNS = {
    "installation_id", "request_id", "operation", "request_sha256",
    "request_json", "state", "result_json", "created_at", "completed_at",
    "source_identity", "adapter_sha256",
}


class OperationError(ValueError):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def fail(code, message):
    raise OperationError(code, message)


def exact(value, fields, label):
    if not isinstance(value, dict):
        fail("invalid_request", label + " must be an object")
    extra = set(value) - fields
    if extra:
        fail("invalid_request", label + " contains unsupported fields: " + ", ".join(sorted(extra)))
    return value


def identifier(value, label="request_id"):
    if not isinstance(value, str) or not REQUEST_ID.fullmatch(value):
        fail("invalid_request", label + " must be a nonempty plain identifier of at most 200 characters")
    return value


def integer(value, label, low=1, high=1000):
    if type(value) is not int or not low <= value <= high:
        fail("invalid_request", label + " must be an integer from " + str(low) + " through " + str(high))
    return value


def absolute(value, label):
    if not isinstance(value, str) or not value or "\x00" in value:
        fail("invalid_request", label + " must be an absolute local path")
    path = pathlib.Path(value)
    if not path.is_absolute():
        fail("invalid_request", label + " must be an absolute local path")
    # Preserve nonexistent selected destinations; existing ancestors are ordinary.
    for part in [path, *path.parents]:
        if part.is_symlink():
            fail("linked_path", label + " cannot traverse a symbolic link")
    return str(path)


def saved_integer(value, label, low=1, high=2**63 - 1):
    if isinstance(value, str) and re.fullmatch(r"[0-9]+", value):
        parsed = int(value)
    elif type(value) is int and abs(value) <= JSON_SAFE_INTEGER:
        parsed = value
    else:
        fail("invalid_request", label + " must be an exact decimal string or a safe JSON integer")
    return integer(parsed, label, low, high)


def event_document(value):
    if not isinstance(value, dict):
        fail("invalid_request", "event must be the original event object")
    result = dict(value)
    result["version"] = saved_integer(result.get("version"), "event.version")
    return result


def configuration_document(value):
    if not isinstance(value, dict):
        fail("invalid_request", "configuration must be an object")
    result = dict(value)
    if isinstance(result.get("routes"), list):
        result["routes"] = [
            {**row, "generation": saved_integer(row.get("generation"), "route.generation")}
            if isinstance(row, dict) else row for row in result["routes"]
        ]
    return result


def precise_json(value):
    if isinstance(value, dict):
        return {key: precise_json(item) for key, item in value.items()}
    if isinstance(value, list):
        return [precise_json(item) for item in value]
    if type(value) is int and abs(value) > JSON_SAFE_INTEGER:
        return str(value)
    return value


def queue_record(value, field=None):
    # Match the original operator's exact SQLite key/revision transport and
    # extend it to this adapter's descending delivery cursor.
    if isinstance(value, dict):
        return {key: queue_record(item, key) for key, item in value.items()}
    if isinstance(value, list):
        return [queue_record(item) for item in value]
    if type(value) is int and field in {"id", "delivery_id", "version", "next_before_version", "next_before_id"}:
        return str(value)
    return value


def public_result(name, value):
    if name in {"queue.status", "queue.list", "queue.get", "jobs.history", "deliveries.resolve"}:
        value = queue_record(value)
    elif name == "installation.inspect":
        value = {**value, "outbox": queue_record(value["outbox"])}
    elif name == "requests.get" and value.get("request") is not None:
        saved = value["request"]
        value = {"request": {**saved, "result": public_result(saved["operation"], saved["result"])
                            if saved["state"] == "completed" else saved["result"]}}
    return precise_json(value)


def optional_path(args, key):
    return absolute(args[key], key) if args.get(key) is not None else None


def optional_python(args):
    value = args.get("python")
    if value is None:
        return None
    if not isinstance(value, str) or not value or "\x00" in value or not pathlib.Path(value).is_absolute():
        fail("invalid_request", "python must be an absolute local executable path")
    # The original native selector resolves executable aliases and records the
    # actual canonical interpreter and version. Keep that selection behavior.
    return str(pathlib.Path(value))


def request(value):
    exact(value, {"schema", "operation", "installation", "arguments", "request_id", "binding"}, "Request")
    if value.get("schema") != REQUEST_SCHEMA:
        fail("invalid_schema", "Select " + REQUEST_SCHEMA)
    name = value.get("operation")
    if name not in ARGUMENTS:
        fail("unknown_operation", "Select a declared TaskerArmy operation")
    args = exact(value.get("arguments", {}), ARGUMENTS[name], "Operation arguments")
    rid = value.get("request_id")
    if rid is not None:
        identifier(rid)
    if name in NAMED_MUTATIONS and rid is None:
        fail("request_id_required", "Retain a request_id before this mutation")
    binding = value.get("binding")
    if binding is not None:
        exact(binding, {"installation_id", "source_identity"}, "Installation binding")
        if not binding or any(not isinstance(v, str) or not v for v in binding.values()):
            fail("invalid_binding", "Installation binding values must be nonempty strings")
        if "source_identity" in binding and not SHA256.fullmatch(binding["source_identity"]):
            fail("invalid_binding", "source_identity must be the selected 64-character SHA-256")
    return {**value, "arguments": args, "request_id": rid}


def identity(value):
    selected = {key: value[key] for key in (
        "installation_id", "operation_id", "source_identity", "paths", "python", "binding"
    ) if key in value}
    if isinstance(selected.get("binding"), dict):
        selected["binding"] = {
            key: str(item) if key in {"device", "inode"} and type(item) is int else item
            for key, item in selected["binding"].items()
        }
    return selected


def original_adoption_transition(req, value, expected_source):
    if req["operation"] != "installation.adopt_source":
        return False
    args = req["arguments"]
    operation_id = identifier(args.get("operation_id", req.get("request_id")), "operation_id")
    application = manage.ordinary(absolute(args.get("application"), "application"), True)
    manifest = manage.source_manifest(application, optional_path(args, "manifest_path"))
    source_id = hashlib.sha256(manage.canonical(manifest).encode("utf-8")).hexdigest()
    adoption_id = hashlib.sha256(manage.canonical({
        "operation_id": operation_id, "source_identity": source_id,
    }).encode("utf-8")).hexdigest()
    if value["source_identity"] != source_id or value.get("source_edition") != adoption_id:
        return False
    root = pathlib.Path(value["paths"]["directory"])
    working = root / "source-adoptions" / adoption_id
    record_path = working / "request.json"
    if not record_path.exists():
        return False
    record = manage.read_json(manage.ordinary(absolute(str(record_path), "original adoption request")))
    previous = record.get("prior_installation")
    if (record.get("schema") != "taskerarmy.source-adoption-request.v1"
            or record.get("operation_id") != operation_id
            or record.get("adoption_id") != adoption_id
            or record.get("source_identity") != source_id
            or record.get("application") != str(application)
            or record.get("installation_id") != value["installation_id"]
            or not isinstance(previous, dict)
            or previous.get("installation_id") != value["installation_id"]
            or previous.get("binding") != value["binding"]
            or previous.get("source_identity") != expected_source):
        return False
    # Check the complete original before/after transition. This reconstructs
    # the original selection for comparison only; the selected native adoption
    # method remains the sole writer and completed-result receiver.
    updated = json.loads(manage.canonical(previous))
    updated["source_identity"] = source_id
    updated["source_edition"] = adoption_id
    updated["paths"]["application"] = str(root / "source-editions" / adoption_id / "application")
    updated["lineage"] = list(previous.get("lineage", [])) + [{
        "source_adoption_id": adoption_id, "operation_id": operation_id,
        "created_at": record["created_at"],
        "previous_source_identity": expected_source, "source_identity": source_id,
    }]
    if updated != value:
        return False
    result_path = working / "result.json"
    if result_path.exists():
        result = manage.read_json(manage.ordinary(absolute(str(result_path), "original adoption result")))
        if (result.get("schema") != "taskerarmy.source-adoption-result.v1"
                or result.get("adoption_id") != adoption_id
                or result.get("operation_id") != operation_id
                or result.get("previous_source_identity") != expected_source
                or result.get("installation") != value):
            return False
    return True


def checked_installation(req):
    root = absolute(req.get("installation"), "installation")
    value = manage.installation(root)
    binding = req.get("binding") or {}
    if "installation_id" in binding and value["installation_id"] != binding["installation_id"]:
        fail("installation_changed", "The selected installation installation_id changed")
    recovery = False
    if "source_identity" in binding and value["source_identity"] != binding["source_identity"]:
        recovery = original_adoption_transition(req, value, binding["source_identity"])
        if not recovery:
            fail("installation_changed", "The selected installation source_identity changed")
    return value, recovery


def selected_module(path, prefix):
    path = manage.ordinary(path)
    key = prefix + hashlib.sha256(str(path).encode("utf-8") + path.read_bytes()).hexdigest()[:24]
    spec = importlib.util.spec_from_file_location(key, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[key] = module
    try:
        spec.loader.exec_module(module)
    except BaseException:
        sys.modules.pop(key, None)
        raise
    return module


@contextlib.contextmanager
def installed_sources(req):
    """Keep the original owner lock while using its selected native modules."""
    global manage, package
    bootstrap_manage, bootstrap_package = manage, package
    root = bootstrap_manage.ordinary(absolute(req.get("installation"), "installation"), True)
    with bootstrap_manage.locked(root):
        value, adoption_recovery = checked_installation(req)
        native = pathlib.Path(value["paths"]["application"]) / "native"
        old_path = list(sys.path)
        prior_archive = sys.modules.get("archive")
        prior_manage = sys.modules.get("manage")
        selected_manage = None
        selected_lock = None
        prior_copy = None
        try:
            sys.path.insert(0, str(native))
            selected_archive = selected_module(native / "archive.py", "taskerarmy_selected_archive_")
            sys.modules["archive"] = selected_archive
            selected_manage = selected_module(native / "manage.py", "taskerarmy_selected_manage_")
            if selected_manage.INSTALL_SCHEMA != bootstrap_manage.INSTALL_SCHEMA:
                fail("native_source_incompatible", "The selected installation requires another native operation adapter")
            if selected_manage.installation(root) != value:
                fail("native_source_identity", "The selected native implementation resolves another installation")
            selected_lock = selected_manage.locked
            prior_copy = selected_manage._COPY_DIRECTORY

            @contextlib.contextmanager
            def original_owned_lock(directory, name=".native.lock"):
                selected = pathlib.Path(directory).resolve(strict=True)
                if selected == root and name == ".native.lock":
                    # This exact original flock remains held by the outer
                    # owner. Re-enter its scope without opening a second flock.
                    yield root
                else:
                    with selected_lock(directory, name) as other:
                        yield other

            selected_manage._COPY_DIRECTORY = root / ".copy-partials"
            selected_manage.locked = original_owned_lock
            manage, package = selected_manage, selected_archive
            sys.modules["manage"] = selected_manage
            yield value, adoption_recovery
        finally:
            manage, package = bootstrap_manage, bootstrap_package
            if selected_manage is not None and selected_lock is not None:
                selected_manage.locked = selected_lock
                selected_manage._COPY_DIRECTORY = prior_copy
            if prior_archive is None:
                sys.modules.pop("archive", None)
            else:
                sys.modules["archive"] = prior_archive
            if prior_manage is None:
                sys.modules.pop("manage", None)
            else:
                sys.modules["manage"] = prior_manage
            sys.path[:] = old_path


def operator_module(value, worker):
    path = manage.ordinary(pathlib.Path(value["paths"]["application"]) / "operator_server.py")
    name = "taskerarmy_selected_operator_" + hashlib.sha256(str(path).encode()).hexdigest()[:16]
    prior = sys.modules.get("notification_outbox")
    sys.modules["notification_outbox"] = worker
    try:
        spec = importlib.util.spec_from_file_location(name, path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module
    finally:
        if prior is None:
            sys.modules.pop("notification_outbox", None)
        else:
            sys.modules["notification_outbox"] = prior


def response(req, value, result, replayed=False):
    return {
        "schema": RESULT_SCHEMA, "ok": True, "operation": req["operation"],
        "request_id": req.get("request_id"),
        "installation": identity(value) if value else None,
        "result": public_result(req["operation"], result), "replayed": bool(replayed),
        "adapter_sha256": ADAPTER_SHA256,
    }


def journal_schema(db):
    db.execute("""CREATE TABLE IF NOT EXISTS taskerarmy_operation_requests (
        installation_id TEXT NOT NULL,
        request_id TEXT NOT NULL,
        operation TEXT NOT NULL,
        request_sha256 TEXT NOT NULL,
        request_json TEXT NOT NULL,
        state TEXT NOT NULL CHECK(state IN ('prepared','completed')),
        result_json TEXT,
        created_at TEXT NOT NULL,
        completed_at TEXT,
        source_identity TEXT NOT NULL,
        adapter_sha256 TEXT NOT NULL,
        PRIMARY KEY (installation_id, request_id)
    )""")
    columns = {row["name"] for row in db.execute("PRAGMA table_info(taskerarmy_operation_requests)")}
    if not JOURNAL_COLUMNS.issubset(columns):
        fail("request_schema_changed", "The original named-operation table has an incompatible schema")


def named_request(req, value):
    # Include the reviewed binding and original path in the original request.
    body = {**req, "installation": value["paths"]["directory"]}
    encoded = manage.canonical(body)
    return encoded, hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def existing_request(db, req, value, checksum):
    row = db.execute(
        "SELECT * FROM taskerarmy_operation_requests WHERE installation_id=? AND request_id=?",
        (value["installation_id"], req["request_id"]),
    ).fetchone()
    if row is not None and (row["request_sha256"] != checksum or row["operation"] != req["operation"]):
        fail("request_conflict", "This request_id already names another complete operation")
    return dict(row) if row is not None else None


def completed_value(record):
    value = json.loads(record["result_json"])
    if isinstance(value, dict) and value.get("schema") == "taskerarmy.operation-rejection.v1":
        error = value["error"]
        fail(error["code"], error["message"])
    return value


def start_request(db, req, value, encoded, checksum, preparation=None):
    db.execute("""INSERT INTO taskerarmy_operation_requests(
        installation_id,request_id,operation,request_sha256,request_json,state,
        result_json,created_at,completed_at,source_identity,adapter_sha256
    ) VALUES(?,?,?,?,?,'prepared',?,?,NULL,?,?)""", (
        value["installation_id"], req["request_id"], req["operation"], checksum,
        encoded, manage.canonical(preparation) if preparation is not None else None,
        manage.utc(), value["source_identity"], ADAPTER_SHA256,
    ))


def complete_request(db, req, value, result):
    db.execute("""UPDATE taskerarmy_operation_requests
        SET state='completed',result_json=?,completed_at=?
        WHERE installation_id=? AND request_id=?""", (
        manage.canonical(result), manage.utc(), value["installation_id"], req["request_id"],
    ))


def atomic_outbox_request(req, value, worker, outbox):
    args = req["arguments"]
    name = req["operation"]
    encoded, checksum = named_request(req, value)
    original_transaction = outbox.transaction
    with original_transaction() as db:
        journal_schema(db)
        previous = existing_request(db, req, value, checksum)
        if previous is not None:
            if previous["state"] == "completed":
                return completed_value(previous), True
            fail("incomplete_atomic_request", "The original atomic request has an unexpected incomplete state")
        # Receive a committed original result before consulting later routing.
        # New authored inputs still pass the unchanged original validators
        # before any durable named request is inserted.
        if name == "events.receive":
            tenant = worker.identifier(args.get("tenant"), "tenant")
            ttl = integer(args.get("ttl_seconds", 86400), "ttl_seconds", 60, 604800)
            event = event_document(args.get("event"))
            worker.validate_event(tenant, event, worker.load_config(outbox.config_path), time.time())
            action = lambda: outbox.record(tenant, event, ttl)
        elif name == "deliveries.resolve":
            delivery = saved_integer(args.get("delivery_id"), "delivery_id")
            outcome = args.get("outcome")
            if outcome not in {"sent", "retry", "cancelled"}:
                fail("invalid_request", "outcome must be sent, retry, or cancelled")
            note = worker.text_value(args.get("note"), "resolution note", 300)
            action = lambda: outbox.resolve(delivery, outcome, note)
        elif name == "routes.resume":
            route = worker.identifier(args.get("route_id"), "route_id")
            action = lambda: outbox.resume_route(route)
        else:
            fail("unknown_operation", "This operation is not an atomic Outbox mutation")
        start_request(db, req, value, encoded, checksum)

        @contextlib.contextmanager
        def same_original_transaction():
            yield db

        # Invoke the original business method inside its original SQLite
        # transaction. Its queue change and this result have one commit.
        outbox.transaction = same_original_transaction
        try:
            result = action()
        finally:
            outbox.transaction = original_transaction
        complete_request(db, req, value, result)
    return result, False

def checked_configuration(args, path, operator, worker):
    revision = args.get("revision")
    if not isinstance(revision, str) or not SHA256.fullmatch(revision):
        fail("invalid_request", "revision must be the exact configuration revision that was opened")
    incoming = configuration_document(args.get("configuration"))
    operator.checked_document(incoming)
    raw = (json.dumps(incoming, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    if len(raw) > operator.MAX_BODY:
        fail("configuration_too_large", "The original configuration limit is 262144 bytes")
    # The original loader validates environment-reference names and every
    # tenant/route field. No supplied secret value is retained before validation.
    fd, name = tempfile.mkstemp(prefix=".operation-configuration-", suffix=".json", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(raw)
        worker.load_config(name)
    finally:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(name)
    return incoming, hashlib.sha256(raw).hexdigest()


def configuration_request(req, value, worker, outbox, operator):
    args = req["arguments"]
    path = pathlib.Path(value["paths"]["configuration"])
    encoded, checksum = named_request(req, value)
    with outbox.transaction() as db:
        journal_schema(db)
        previous = existing_request(db, req, value, checksum)
        if previous is not None and previous["state"] == "completed":
            return completed_value(previous), True
        if previous is None:
            incoming, target = checked_configuration(args, path, operator, worker)
            current = package.digest_file(path)
            if current != args["revision"]:
                fail("configuration_changed", "Configuration changed. Read it and compose the selected edit.")
            start_request(db, req, value, encoded, checksum, {
                "previous_revision": args["revision"], "target_revision": target,
            })
        else:
            # This exact named request passed document validation before its
            # prepared record committed. The original writer still owns
            # transition checks. Reconciliation needs these retained bytes,
            # not another temporary document-validation file.
            incoming = configuration_document(args["configuration"])
            raw = (json.dumps(incoming, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
            target = hashlib.sha256(raw).hexdigest()
            preparation = json.loads(previous["result_json"])
            if preparation != {"previous_revision": args["revision"], "target_revision": target}:
                fail("request_conflict", "The retained original configuration selection differs")
    current = package.digest_file(path)
    if previous is not None and current == target:
        # The original atomic file replacement committed before the result
        # write. Receive the already-selected source, without another write.
        pass
    elif current == args["revision"]:
        try:
            selected = operator.save_configuration(path, args["revision"], incoming)
        except (operator.InputError, operator.OperatorError) as exc:
            # These original validation/CAS refusals occur before replacement.
            # Retain that actual terminal outcome; an I/O failure may happen
            # after replacement and therefore keeps the prepared selection.
            code = getattr(exc, "code", "configuration_rejected")
            if not isinstance(code, str):
                code = "configuration_rejected"
            rejection = {
                "schema": "taskerarmy.operation-rejection.v1",
                "error": {"code": code, "message": str(exc)[:1000]},
                "previous_revision": args["revision"], "target_revision": target,
            }
            with outbox.transaction() as db:
                journal_schema(db)
                saved = existing_request(db, req, value, checksum)
                if saved is None:
                    fail("request_missing", "The original configuration request disappeared")
                if saved["state"] == "completed":
                    return completed_value(saved), True
                complete_request(db, req, value, rejection)
            fail(code, rejection["error"]["message"])
        if selected != target:
            fail("configuration_identity", "The original configuration writer returned another revision")
    else:
        fail("configuration_outcome_changed",
             "The current configuration differs from both retained revisions; inspect this request and current configuration.")
    result = {
        "revision": target, "configuration": incoming,
        "credentials": {
            "tenants": {key: bool(os.environ.get(row["ingress_token_env"]))
                        for key, row in incoming["tenants"].items()},
            "routes": {row["id"]: bool(os.environ.get(row["webhook_env"]))
                       for row in incoming["routes"]},
        },
    }
    with outbox.transaction() as db:
        journal_schema(db)
        saved = existing_request(db, req, value, checksum)
        if saved is None:
            fail("request_missing", "The original configuration request disappeared")
        if saved["state"] == "completed":
            return completed_value(saved), True
        complete_request(db, req, value, result)
    return result, previous is not None

def list_queue(args, worker, outbox):
    limit = integer(args.get("limit", 100), "limit")
    where, values = [], []
    for key, column in (
        ("tenant", "tenant_id"), ("status", "status"),
        ("route_id", "route_id"), ("job_id", "job_id"),
    ):
        if args.get(key) is not None:
            value = worker.identifier(args[key], key)
            where.append(column + "=?")
            values.append(value)
    filters = " WHERE " + " AND ".join(where) if where else ""
    before = args.get("before_id")
    if before is not None:
        before = saved_integer(before, "before_id")
    page_where = list(where)
    page_values = list(values)
    if before is not None:
        page_where.append("id<?")
        page_values.append(before)
    page_filter = " WHERE " + " AND ".join(page_where) if page_where else ""
    with contextlib.closing(outbox.connect()) as db:
        # Counts and this full page refer to one original SQLite read snapshot.
        db.execute("BEGIN")
        counts = [dict(row) for row in db.execute(
            "SELECT status,COUNT(*) AS count FROM deliveries" + filters + " GROUP BY status ORDER BY status",
            values,
        )]
        rows = [dict(row) for row in db.execute(
            "SELECT " + ",".join(QUEUE_FIELDS) + " FROM deliveries" + page_filter +
            " ORDER BY id DESC LIMIT ?", [*page_values, limit + 1],
        )]
        db.rollback()
    more = len(rows) > limit
    rows = rows[:limit]
    return {
        "deliveries": rows, "counts": counts,
        "total": sum(row["count"] for row in counts),
        "next_before_id": rows[-1]["id"] if more else None,
        "filters": {key: args[key] for key in ("tenant", "status", "route_id", "job_id") if args.get(key) is not None},
    }


@contextlib.contextmanager
def original_journal(value):
    # A completed request remains receivable even when a later configuration
    # edit is invalid or new temporary files cannot be created.
    path = manage.ordinary(value["paths"]["database"])
    db = sqlite3.connect(path.as_uri() + "?mode=ro", uri=True, timeout=10, isolation_level=None)
    db.row_factory = sqlite3.Row
    try:
        db.execute("PRAGMA query_only=ON")
        yield db
    finally:
        db.close()


def journal_exists(db):
    return db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (JOURNAL,)).fetchone() is not None


def completed_request(req, value):
    _, checksum = named_request(req, value)
    with original_journal(value) as db:
        if not journal_exists(db):
            return None
        saved = existing_request(db, req, value, checksum)
    if saved is not None and saved["state"] == "completed":
        return completed_value(saved), True
    return None


def get_request(args, value):
    rid = identifier(args.get("request_id"))
    installation_id = args.get("installation_id", value["installation_id"])
    identifier(installation_id, "installation_id")
    with original_journal(value) as db:
        if not journal_exists(db):
            return {"request": None}
        row = db.execute(
            "SELECT * FROM taskerarmy_operation_requests WHERE installation_id=? AND request_id=?",
            (installation_id, rid),
        ).fetchone()
    if row is None:
        return {"request": None}
    item = dict(row)
    item["request"] = json.loads(item["request_json"])
    saved = item.pop("result_json")
    item["result"] = json.loads(saved) if saved else None
    return {"request": item}

def describe_commands(args, value, worker):
    roles = args.get("roles", ["operator", "ingress", "worker"])
    if (not isinstance(roles, list) or not roles
            or any(not isinstance(role, str) or role not in {"operator", "ingress", "worker"} for role in roles)
            or len(set(roles)) != len(roles)):
        fail("invalid_request", "roles must select distinct operator, ingress, or worker services")
    operator_port = integer(args.get("operator_port", 0), "operator_port", 0, 65535)
    ingress_port = integer(args.get("ingress_port", 8094), "ingress_port", 1, 65535)
    interval = args.get("worker_interval", 2.0)
    if isinstance(interval, bool) or not isinstance(interval, (int, float)) or not 0.1 <= interval <= 60:
        fail("invalid_request", "worker_interval must be from 0.1 through 60 seconds")
    token_env = args.get("operator_token_env", "TASKER_OPERATOR_TOKEN")
    if not isinstance(token_env, str) or not worker.ENV.fullmatch(token_env):
        fail("invalid_request", "operator_token_env must be an environment-reference name")
    ready = absolute(args.get("ready_file"), "ready_file") if "operator" in roles else None
    app = pathlib.Path(value["paths"]["application"])
    executable = str(manage.ordinary(value["python"]["path"]))
    worker_path = str(manage.ordinary(app / "notification_outbox.py"))
    config = worker.load_config(value["paths"]["configuration"])
    references = {
        "operator": [token_env],
        "ingress": sorted({row["ingress_token_env"] for row in config["tenants"].values()}),
        "worker": sorted({row["webhook_env"] for row in config["routes"] if row["enabled"]}),
    }
    common = [executable, "-B", worker_path, "--db", value["paths"]["database"],
              "--config", value["paths"]["configuration"]]
    commands = []
    for role in roles:
        if role == "operator":
            script = str(manage.ordinary(app / "native" / "launch_operator.py"))
            argv = [executable, "-B", script, "--directory", value["paths"]["directory"],
                    "--ready-file", ready, "--port", str(operator_port), "--token-env", token_env]
            health = {"kind": "private-ready-file", "path": ready,
                      "schema": "taskerarmy.operator-process.v1"}
        elif role == "ingress":
            script = worker_path
            argv = common + ["serve", "--host", "127.0.0.1", "--port", str(ingress_port)]
            health = {"kind": "http", "url": "http://127.0.0.1:" + str(ingress_port) + "/healthz"}
        else:
            script = worker_path
            argv = common + ["run", "--interval", str(interval)]
            health = {"kind": "managed-process"}
        commands.append({
            "role": role, "executable": executable, "argv": argv, "cwd": str(app),
            "script": script, "script_sha256": package.digest_file(script),
            "ready_file": ready if role == "operator" else None,
            "health": health,
            "environment_references": [
                {"name": name, "present": bool(os.environ.get(name))} for name in references[role]
            ],
        })
    return {"commands": commands, "installation": identity(value)}


def perform(raw):
    req = request(raw)
    name, args = req["operation"], req["arguments"]
    if name == "installation.prepare":
        operation_id = identifier(args.get("operation_id", req.get("request_id")), "operation_id")
        result = manage.prepare(
            absolute(args.get("application"), "application"),
            absolute(args.get("configuration"), "configuration"),
            absolute(args.get("directory"), "directory"),
            optional_path(args, "manifest_path"), optional_python(args), operation_id,
        )
        value = result.get("installation", result)
        if value.get("schema") != manage.INSTALL_SCHEMA:
            value = manage.installation(args["directory"])
        return response(req, value, result, result.get("replayed", False))
    if name == "installation.receive":
        result = manage.receive(
            absolute(args.get("archive_path"), "archive_path"),
            absolute(args.get("directory"), "directory"), optional_python(args),
        )
        return response(req, result["installation"], result, result.get("replayed", False))

    # The selected archive/manage/worker/operator all come from this actual
    # installed application. Its original flock spans selection and operation.
    with installed_sources(req) as selected:
        value, adoption_recovery = selected
        root = value["paths"]["directory"]
        if name == "installation.inspect":
            return response(req, value, manage.inspect(root))
        if name == "installation.adopt_source":
            operation_id = identifier(args.get("operation_id", req.get("request_id")), "operation_id")
            result = manage.adopt_source(
                root, absolute(args.get("application"), "application"),
                optional_path(args, "manifest_path"), operation_id,
            )
            return response(req, manage.installation(root), result, adoption_recovery or result.get("replayed", False))
        if name == "installation.snapshot":
            operation_id = identifier(args.get("operation_id", req.get("request_id")), "operation_id")
            result = manage.snapshot(root, absolute(args.get("output"), "output"), operation_id)
            replayed = result.get("replayed", False) or result.get("recovered_original_output", False)
            return response(req, value, result, replayed)
        if name in NAMED_MUTATIONS:
            completed = completed_request(req, value)
            if completed is not None:
                return response(req, value, completed[0], completed[1])
        if name == "requests.get":
            return response(req, value, get_request(args, value))

        worker, outbox = manage.outbox_for(value)
        operator = operator_module(value, worker)
        if name == "configuration.read":
            result = operator.public_configuration(pathlib.Path(value["paths"]["configuration"]))
        elif name == "configuration.save":
            result, replayed = configuration_request(req, value, worker, outbox, operator)
            return response(req, value, result, replayed)
        elif name in {"events.receive", "deliveries.resolve", "routes.resume"}:
            result, replayed = atomic_outbox_request(req, value, worker, outbox)
            return response(req, value, result, replayed)
        elif name == "queue.status":
            tenant = worker.identifier(args["tenant"], "tenant") if args.get("tenant") is not None else None
            result = outbox.status(tenant, integer(args.get("limit", 100), "limit"))
        elif name == "queue.list":
            result = list_queue(args, worker, outbox)
        elif name == "queue.get":
            result = operator.safe_delivery(outbox.inspect(saved_integer(args.get("delivery_id"), "delivery_id")))
        elif name == "jobs.history":
            limit = integer(args.get("limit", 100), "limit")
            before = args.get("before_version")
            if before is not None:
                before = saved_integer(before, "before_version")
            result = outbox.job_timeline(
                worker.identifier(args.get("tenant"), "tenant"),
                worker.identifier(args.get("job"), "job"), before, limit,
            )
        elif name == "events.render":
            config = worker.load_config(outbox.config_path)
            event, _ = worker.validate_event(
                worker.identifier(args.get("tenant"), "tenant"), event_document(args.get("event")), config, time.time(),
            )
            result = worker.slack_payload(event, config["product_name"])
        elif name == "commands.describe":
            result = describe_commands(args, value, worker)
        else:
            fail("unknown_operation", "Select a declared TaskerArmy operation")
    return response(req, value, result)


def decode_request(raw):
    if len(raw) > MAX_REQUEST:
        fail("request_too_large", "Operation requests are limited to 2097152 bytes")

    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                fail("duplicate_json_field", "The operation request contains a repeated JSON field")
            result[key] = value
        return result

    def constant(_):
        fail("invalid_json_number", "JSON numbers must be finite")

    return json.loads(raw.decode("utf-8"), object_pairs_hook=unique, parse_constant=constant)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--request", help="One UTF-8 JSON request file; omit or use - for stdin")
    args = parser.parse_args(argv)
    req = None
    try:
        if args.request and args.request != "-":
            path = manage.ordinary(absolute(args.request, "request"))
            with path.open("rb") as stream:
                raw = stream.read(MAX_REQUEST + 1)
        else:
            raw = sys.stdin.buffer.read(MAX_REQUEST + 1)
        req = decode_request(raw)
        result = perform(req)
        print(json.dumps(result, ensure_ascii=False, allow_nan=False), flush=True)
        return 0
    except Exception as exc:
        code = getattr(exc, "code", None)
        if not isinstance(code, str):
            if isinstance(exc, sqlite3.Error):
                code = "database_operation_failed"
            elif isinstance(exc, (OSError, IOError)):
                code = "local_source_operation_failed"
            elif isinstance(exc, (json.JSONDecodeError, UnicodeError, ValueError, TypeError)):
                code = "invalid_request"
            else:
                code = "operation_failed"
        # Exceptions from these original validators name fields and local
        # source operations. Never print an environment, request body or traceback.
        result = {
            "schema": RESULT_SCHEMA, "ok": False,
            "operation": req.get("operation") if isinstance(req, dict) and isinstance(req.get("operation"), str) else None,
            "request_id": req.get("request_id") if isinstance(req, dict) and isinstance(req.get("request_id"), str) else None,
            "error": {"code": code, "message": str(exc)[:1000]},
            "adapter_sha256": ADAPTER_SHA256,
        }
        print(json.dumps(result, ensure_ascii=False, allow_nan=False), flush=True)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

{
  "version": 1,
