// MIT. Metadata and lazy hooks for an original source-owned merchant provider.
export const MERCHANT_PROVIDER_SCHEMA = 'stellar-forge.merchant-provider.v1';
export const CORE_MERCHANT_CONFIG_KEYS = Object.freeze(['schema', 'name', 'releaseStore', 'exportsDirectory', 'sources']);
const idPattern = /^[a-z][a-z0-9-]{0,63}$/;
const familyPattern = /^[a-z][A-Za-z0-9]{0,63}$/;
const toolPattern = /^[a-zA-Z0-9_.-]{1,128}$/;
const reserved = new Set([...CORE_MERCHANT_CONFIG_KEYS, 'core', 'constructor', 'prototype', '__proto__']);
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
function ensure(value, message) {
  if (!value) throw Object.assign(new TypeError(message), { code: 'MERCHANT_PROVIDER_INVALID' });
}
function name(value, label, pattern = familyPattern) {
  ensure(typeof value === 'string' && pattern.test(value) && !reserved.has(value), 'Invalid merchant provider ' + label + ': ' + value);
  return value;
}
function names(values, label, pattern = familyPattern) {
  ensure(Array.isArray(values), 'Expected merchant provider ' + label + ' array.');
  const result = values.map(value => name(value, label, pattern));
  ensure(new Set(result).size === result.length, 'Duplicate merchant provider ' + label + '.');
  return Object.freeze(result);
}
function order(value, label) {
  ensure(Number.isSafeInteger(value) && value >= 0 && value <= 1000000, 'Invalid merchant provider ' + label + '.');
  return value;
}
function flag(value, label) {
  ensure(typeof value === 'boolean', 'Expected boolean merchant provider ' + label + '.');
  return value;
}
/**
 * Declaration modules import tool metadata only. Native source, configuration
 * readers and setup implementations remain behind the corresponding lazy hooks.
 * Runtime ownership uses MerchantProviderOwners and its original lifecycle ABI.
 */
export function defineMerchantProvider(value) {
  ensure(plain(value) && value.schema === MERCHANT_PROVIDER_SCHEMA, 'Expected an original merchant provider declaration.');
  const fields = new Set(['schema', 'id', 'family', 'title', 'order', 'catalogOrder', 'configKey',
    'configuration', 'summary', 'dependencies', 'load', 'create', 'tools', 'coreToolNames',
    'maxRequestBytes', 'concurrency', 'concurrentTools', 'shutdown', 'requestClose', 'instructions', 'initialize']);
  ensure(Object.keys(value).every(key => fields.has(key)), 'Unknown merchant provider declaration field for ' + value.id + '.');
  name(value.id, 'ID', idPattern); name(value.family, 'family');
  ensure(typeof value.title === 'string' && value.title.trim() && value.title.length <= 160,
    'Expected a merchant provider title for ' + value.id + '.');
  ensure(value.configKey === null || typeof value.configKey === 'string', 'Expected a configuration key or null for ' + value.id + '.');
  if (value.configKey !== null) name(value.configKey, 'configuration key');
  for (const key of ['load', 'create', 'tools']) ensure(typeof value[key] === 'function', 'Expected ' + value.id + '.' + key + ' hook.');
  for (const key of ['initialize', 'requestClose'])
    ensure(value[key] === undefined || typeof value[key] === 'function', 'Expected ' + value.id + '.' + key + ' hook.');
  const concurrency = value.concurrency ?? 'host', shutdown = value.shutdown ?? 'drain';
  ensure(['host', 'provider'].includes(concurrency), 'Unknown concurrency owner for ' + value.id + '.');
  ensure(['drain', 'provider'].includes(shutdown), 'Unknown shutdown owner for ' + value.id + '.');
  const maximum = value.maxRequestBytes ?? 128 * 1024;
  ensure(Number.isSafeInteger(maximum) && maximum > 0, 'Expected a positive original request-byte limit for ' + value.id + '.');
  let configuration = null;
  if (value.configuration !== undefined && value.configuration !== null) {
    const source = value.configuration;
    ensure(plain(source) && Object.keys(source).every(key => ['input', 'read', 'dependencies', 'privateExports'].includes(key)),
      'Unknown configuration declaration for ' + value.id + '.');
    ensure(value.configKey !== null && typeof source.read === 'function', 'Expected a configuration reader for ' + value.id + '.');
    name(source.input, 'host configuration input');
    configuration = Object.freeze({ ...source,
      dependencies: names(source.dependencies ?? [], 'configuration dependency'),
      privateExports: flag(source.privateExports ?? false, 'privateExports') });
  }
  ensure(value.configKey === null || configuration, 'A configured merchant provider must declare its original reader: ' + value.id);
  ensure(Array.isArray(value.instructions ?? []), 'Expected instruction sections for ' + value.id + '.');
  const instructions = (value.instructions ?? []).map(section => {
    ensure(plain(section) && Object.keys(section).every(key => ['order', 'prefix', 'tool', 'text'].includes(key)),
      'Unknown instruction section for ' + value.id + '.');
    ensure(typeof section.text === 'string' && section.text.length > 0 && section.text.length <= 65536,
      'Expected original instruction text for ' + value.id + '.');
    ensure(Object.hasOwn(section, 'prefix') !== Object.hasOwn(section, 'tool'),
      'An instruction selects one prefix or exact tool for ' + value.id + '.');
    if (Object.hasOwn(section, 'prefix')) ensure(section.prefix === null ||
      typeof section.prefix === 'string' && section.prefix.length > 0 && section.prefix.length <= 128,
    'Invalid instruction prefix for ' + value.id + '.');
    if (Object.hasOwn(section, 'tool')) name(section.tool, 'instruction tool', toolPattern);
    return Object.freeze({ ...section, order: order(section.order ?? value.order ?? 1000, 'instruction order') });
  });
  return Object.freeze({ ...value,
    order: order(value.order ?? 1000, 'order'),
    catalogOrder: order(value.catalogOrder ?? value.order ?? 1000, 'catalog order'),
    configuration, summary: flag(value.summary ?? true, 'summary'),
    dependencies: names(value.dependencies ?? [], 'dependency'),
    coreToolNames: names(value.coreToolNames ?? [], 'core tool', toolPattern),
    concurrentTools: names(value.concurrentTools ?? [], 'concurrent tool', toolPattern),
    maxRequestBytes: maximum, concurrency, shutdown, instructions: Object.freeze(instructions) });
}

// MIT. Shared mechanics for source-owned original Applications adapters.
import { StringDecoder } from 'node:string_decoder';
import { access, realpath } from 'node:fs/promises';
import { constants } from 'node:fs';
import { join } from 'node:path';
import { need, plain, saveJSON, now } from './storage.mjs';

export const APPLICATION_PROVIDER_SCHEMA = 'stellar-forge.runtime-application-provider.v1';
export const applicationField = (name, label, type = 'path', required = false, description = '') =>
  ({ name, label, type, required, description });
export const applicationCommonFields = Object.freeze([
  applicationField('port', 'Local port', 'port', false,
    'Use 0 to let the original application choose an available port.'),
  applicationField('environmentFile', 'Private environment JSON', 'path', false,
    'Optional private file containing environment names and string values. Values stay on this host.'),
]);

/** Original path and argv helpers for adapters moved out of the shared dispatcher. */
export function applicationPreparation(settings, inputPath) {
  const args = [], inputs = [], createDirectories = [];
  return {
    args, inputs, createDirectories,
    async path(name, kind = 'directory', missing = false, privateOnly = false) {
      if (!settings[name]) return;
      const value = await inputPath(settings[name], kind, missing, privateOnly);
      inputs.push(value); return value;
    },
    option(name, value) {
      if (value !== undefined && value !== '') args.push(name, String(value));
    },
  };
}

/** Keep the original common port, private environment and terminal preparation. */
export async function prepareProviderApplication(provider, type, settings, context) {
  const selected = await provider.prepare(type, settings, context);
  need(plain(selected) && Array.isArray(selected.args) &&
    selected.args.every(value => typeof value === 'string') &&
    Array.isArray(selected.inputs) && Array.isArray(selected.createDirectories),
  'APPLICATION_PROVIDER_PREPARATION_INVALID', 'The ' + provider.id + ' provider returned an invalid original command.');
  if (provider.completeCommand === true) {
    need(selected.command === type.command && selected.terminal === type.terminal,
      'APPLICATION_PROVIDER_COMMAND_CHANGED', 'The original provider command differs from its catalog.');
    return selected;
  }
  const args = [...selected.args], inputs = [...selected.inputs];
  let terminalPython;
  if (type.terminal) {
    terminalPython = await realpath(settings.terminalPython ?? '/usr/bin/python3');
    inputs.push(await context.inputPath(terminalPython, 'file'));
    await access(terminalPython, constants.X_OK);
  }
  if (provider.appendPort !== false && settings.port !== undefined && settings.port !== '')
    args.push('--port', String(settings.port));
  if (settings.environmentFile) inputs.push(await context.inputPath(settings.environmentFile, 'file'));
  const environment = await context.applicationEnvironment(settings.environmentFile);
  return { ...selected, command: type.command, args, inputs, terminal: type.terminal,
    ...(type.terminal ? { terminalPython } : {}),
    ...(settings.environmentFile ?
      { environmentFile: settings.environmentFile, environmentSha256: environment.sha256 } : {}) };
}

/** Bind run-specific arguments only when the reviewed original operation is retained. */
export function retainedApplicationArguments(provider, command, requestId) {
  const args = provider.runArguments
    ? provider.runArguments({command:command.command, args:[...command.args], requestId})
    : [...command.args];
  need(Array.isArray(args) && args.every(value => typeof value === 'string'),
    'APPLICATION_PROVIDER_RUN_ARGUMENTS_INVALID',
    'The ' + provider.id + ' provider must return the original managed argument list.');
  return args;
}

export function applicationPrivateUrl(text) {
  try {
    const url = new URL(text);
    if (url.protocol !== 'http:' || !['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname) ||
        Number(url.port || 80) < 1 || Number(url.port || 80) > 65535 ||
        url.username || url.password || text.length > 4096) return null;
    return url.href;
  } catch { return null; }
}

/**
 * A provider synchronously reads original normalized startup lines. It returns a URL,
 * {url, original?, links?, workspaceId?, connectionFile?}, a deferred resolver function, an array of those values, or null.
 * Defer asynchronous source checks so ignored later announcements never run them. Stateful original
 * multi-line readers live in that provider. This one writer retains the first
 * accepted announcement, its original identity and the shared operation ID.
 */
export function observeApplicationStartup(request, directory, readLine, { lineLimit = 16384 } = {}) {
  need(typeof readLine === 'function', 'APPLICATION_PROVIDER_OBSERVER_REQUIRED');
  need(Number.isSafeInteger(lineLimit) && lineLimit >= 1 && lineLimit <= 1024 * 1024,
    'APPLICATION_PROVIDER_LINE_LIMIT_INVALID');
  let buffer = '', seen = false, closed = false, saveError = null, saving = Promise.resolve();
  const decoder = new StringDecoder('utf8');
  function line(value) {
    if (seen || !request.applicationId) return;
    const text = value.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '').trim();
    let result;
    try { result = readLine(text); }
    catch (error) { saveError = error; return; }
    for (const selected of Array.isArray(result) ? result : [result]) {
      if (!selected) continue;
      saving = saving.then(async () => {
        if (seen) return;
        const candidate = typeof selected === 'function' ? await selected() : await selected;
        const startup = typeof candidate === 'string' ? { url: candidate } : candidate;
        const url = startup && applicationPrivateUrl(startup.url);
        if (!url) return;
        seen = true;
        await saveJSON(join(directory, 'application-url.json'), {
          schema: 'stellar-forge.application-url.v1', applicationId: request.applicationId,
          operationId: directory.split('/').at(-1), command: request.command,
          source: 'original-command-stdout', observedAt: now(), url,
          ...(Object.hasOwn(startup, 'links') ? { links: startup.links } : {}),
          ...(Object.hasOwn(startup, 'original') ? { original: startup.original } : {}),
          ...(Object.hasOwn(startup, 'workspaceId') ? { workspaceId: startup.workspaceId } : {}),
          ...(Object.hasOwn(startup, 'connectionFile') ? { connectionFile: startup.connectionFile } : {}),
        });
      }).catch(error => { if (error.code !== 'EEXIST') saveError = error; });
    }
  }
  return {
    write(bytes) {
      if (!request.applicationId || seen || closed) return;
      buffer += decoder.write(bytes);
      const lines = buffer.split(/\r?\n/); buffer = lines.pop();
      for (const text of lines) line(text);
      if (buffer.length > lineLimit) buffer = buffer.slice(-lineLimit);
    },
    async close() {
      if (!closed) { closed = true; buffer += decoder.end(); if (buffer) line(buffer); }
      await saving; if (saveError) throw saveError;
    },
  };
}

// MIT. Private retained records for the original runtime operator workspace.
import { constants } from 'node:fs';
import { open, mkdir, lstat, realpath, rename, readFile, link, unlink } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { spawnSync } from 'node:child_process';

export const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export const now = () => new Date().toISOString();
export const digest = value => createHash('sha256').update(value).digest('hex');
export const json = value => JSON.stringify(value, null, 2) + '\n';
export const fail = (code, message = code, status = 400) => { throw Object.assign(new Error(message), { code, status }); };
export const need = (value, code, message, status) => { if (!value) fail(code, message, status); };
export function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  return plain(value) ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;
}
export function recordId(value) {
  need(typeof value === 'string' && /^[a-f0-9]{24}$/.test(value), 'RUNTIME_WORKSPACE_RECORD_INVALID');
  return value;
}
export function operationId(value) {
  need(typeof value === 'string' && /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(value),
    'RUNTIME_WORKSPACE_OPERATION_INVALID');
  return value;
}
export function absolute(value) {
  need(typeof value === 'string' && value && value === resolve(value) && !value.includes('\0'),
    'RUNTIME_WORKSPACE_ABSOLUTE_PATH_REQUIRED');
  return value;
}
export async function privateDirectory(value) {
  const path = absolute(value), info = await lstat(path);
  need(info.isDirectory() && !info.isSymbolicLink() && await realpath(path) === path &&
    !(info.mode & 0o077) && (process.getuid === undefined || info.uid === process.getuid()),
  'RUNTIME_WORKSPACE_PRIVATE_DIRECTORY_REQUIRED', 'Use a private real directory owned by the current operator');
  return path;
}
export async function makePrivate(value) {
  const path = absolute(value);
  need(await realpath(dirname(path)) === dirname(path), 'RUNTIME_WORKSPACE_REAL_PARENT_REQUIRED');
  await mkdir(path, { mode: 0o700 });
  return privateDirectory(path);
}
export async function regular(path, maximum = 4 * 1024 * 1024) {
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const first = await handle.stat();
    need(first.isFile() && first.size <= maximum, 'RUNTIME_WORKSPACE_FILE_INVALID');
    const bytes = await handle.readFile(), last = await handle.stat();
    need(bytes.length <= maximum && first.size === last.size && first.mtimeMs === last.mtimeMs &&
      first.ctimeMs === last.ctimeMs, 'RUNTIME_WORKSPACE_FILE_CHANGED');
    return bytes;
  } finally { await handle.close(); }
}
export async function readJSON(path, optional = false) {
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(await regular(path))); }
  catch (error) { if (optional && error.code === 'ENOENT') return null; throw error; }
}
export async function saveJSON(path, value, replace = false) {
  const temporary = path + '.pending-' + randomUUID();
  const handle = await open(temporary, 'wx', 0o600);
  try { await handle.writeFile(json(value)); await handle.sync(); }
  finally { await handle.close(); }
  if (replace) await rename(temporary, path);
  else {
    try { await link(temporary, path); }
    finally { await unlink(temporary); }
  }
  const parent = await open(dirname(path), constants.O_RDONLY | constants.O_DIRECTORY);
  try { await parent.sync(); } finally { await parent.close(); }
}
export async function processIdentity(pid = process.pid) {
  try {
    if (!Number.isInteger(pid) || pid <= 0) return null;
    const selfText = await readFile('/proc/self/stat', 'utf8');
    const selfPid = Number(selfText.slice(0, selfText.indexOf(' ')));
    const parse = text => {
      const fields = text.slice(text.lastIndexOf(')') + 2).trim().split(/\s+/);
      return fields[0] === 'Z' ? null : fields[19] ?? null;
    };
    if (pid === process.pid) return parse(selfText);
    if (selfPid === process.pid) return parse(await readFile('/proc/' + pid + '/stat', 'utf8'));
    const selfStatus = await readFile('/proc/self/status', 'utf8');
    const ownIds = selfStatus.match(/^NSpid:\s+(.+)$/m)?.[1].trim().split(/\s+/);
    if (!ownIds) return null;
    const depth = ownIds.length - 1, pending = [selfPid], visited = new Set();
    // Only resolve this process's descendants. A receiving server in a
    // different namespace relies on the original kernel lease and stop file.
    while (pending.length && visited.size < 256) {
      const parent = pending.shift();
      if (visited.has(parent)) continue;
      visited.add(parent);
      let children;
      try { children = (await readFile('/proc/' + parent + '/task/' + parent + '/children', 'utf8')).trim().split(/\s+/).filter(Boolean); }
      catch { continue; }
      for (const child of children) {
        try {
          const status = await readFile('/proc/' + child + '/status', 'utf8');
          const ids = status.match(/^NSpid:\s+(.+)$/m)?.[1].trim().split(/\s+/);
          if (ids && Number(ids[depth]) === pid)
            return parse(await readFile('/proc/' + child + '/stat', 'utf8'));
          pending.push(Number(child));
        } catch {}
      }
    }
    return null;
  } catch { return null; }
}
export async function workerAlive(state) {
  return Number.isInteger(state?.pid) && typeof state?.processStart === 'string' &&
    await processIdentity(state.pid) === state.processStart;
}
export async function operationLease(path) {
  const handle = await open(path, constants.O_RDWR | constants.O_CREAT | constants.O_NOFOLLOW, 0o600);
