    {signal: AbortSignal.timeout(1000)}); return result.status === 200; }, 'Original ingress health');
  const ingressEvent = event('native-ingress-event', 'native-ingress-job', 1);
  const received = await fetch('http://127.0.0.1:' + ingressPort + '/v1/events', {
    method: 'POST', headers: {'content-type': 'application/json', 'x-notification-tenant': 'native-tenant',
      authorization: 'Bearer ' + ingressToken}, body: JSON.stringify(ingressEvent), signal: AbortSignal.timeout(5000)});
  assert.equal(received.status, 202);
  const ingressResult = await received.json(); assert.equal(ingressResult.queued, 1);
  await stop(ingress.child); await ingress.observer.close();
  await stage('actual authenticated native ingress into the shared database', {port: ingressPort, result: ingressResult});

  const worker = await launchRole(appTypes.find(row => row.id === 'tasker-worker'), {directory, python, interval: '0.1'});
  const failed = await until(async () => {
    const queue = await call('queue', {status: 'route_failed', limit: 100});
    return queue.result.deliveries.length ? queue.result.deliveries[0] : null;
  }, 'Original worker configuration failure');
  await stop(worker.child); await worker.observer.close();
  assert.equal(failed.last_error, 'webhook_configuration');
  const resolved = await call('resolve_delivery', {requestId: ids.resolve, deliveryId: failed.id,
    outcome: 'cancelled', note: 'Native receiving run: missing selected webhook, cancel this original delivery.'});
  const resolvedAgain = await call('resolve_delivery', {requestId: ids.resolve, deliveryId: failed.id,
    outcome: 'cancelled', note: 'Native receiving run: missing selected webhook, cancel this original delivery.'});
  assert(resolvedAgain.replayed); assert.equal(resolved.result.status, 'cancelled');
  const resumed = await call('resume_route', {requestId: ids.resume, routeId: 'native-route'});
  const resumedAgain = await call('resume_route', {requestId: ids.resume, routeId: 'native-route'});
  assert(resumedAgain.replayed);
  await retained('WORKER_RECOVERY.json', {failed, resolved, resolvedAgain, resumed, resumedAgain});
  await stage('original managed worker, route failure and operator recovery replay',
    {delivery_id: failed.id, resolution: resolved.result.status, resumed: resumed.result.resumed});

  await owner.close(); owner = null;
  const nextSource = join(root, 'selected-next-source');
  await cp(source, nextSource, {recursive: true});
  await writeFile(join(nextSource, 'NATIVE_EDITION.md'), 'Selected complete native receiving edition.\n', {mode: 0o600});
  const pinned = clientFor(directory, {installation_id: origin.installation_id, source_identity: origin.source_identity});
  const adoptionInput = {application: nextSource, operation_id: ids.adopt};
  const adopted = await pinned.call('installation.adopt_source', adoptionInput, ids.adopt);
  const adoptedAgain = await pinned.call('installation.adopt_source', adoptionInput, ids.adopt);
  assert(adoptedAgain.replayed);
  assert.equal(adopted.installation.source_identity, adoptedAgain.installation.source_identity);
  assert.notEqual(adopted.installation.source_identity, origin.source_identity);
  await assert.rejects(() => pinned.inspect(), error => error.code === 'installation_changed');
  const current = clientFor(directory, {installation_id: origin.installation_id, source_identity: adopted.installation.source_identity});
  const currentInspection = await current.inspect();
  await retained('SOURCE_ADOPTION.json', {adopted, adoptedAgain, currentInspection});
  await stage('pinned source adoption and exact lost-response replay',
    {installation_id: origin.installation_id, previous_source: origin.source_identity, source_identity: adopted.installation.source_identity});

  const archive = join(transfer, 'complete-original.tar.gz');
  const snapshot = await current.snapshot(archive, ids.snapshot);
  const snapshotAgain = await current.snapshot(archive, ids.snapshot);
  assert(snapshotAgain.replayed);
  const destination = join(root, 'received');
  const receiving = clientFor(destination);
  const independent = await receiving.receive({archive_path: archive, python}, ids.receive);
  const independentAgain = await receiving.receive({archive_path: archive, python}, ids.receive);
  assert(independentAgain.replayed);
  assert.notEqual(independent.installation.installation_id, origin.installation_id);
  const receivedHistory = await receiving.history('native-tenant', 'native-job-a', {limit: 100});
  assert.equal(receivedHistory.result.job.version, '9007199254740994');
  const copiedRequest = await receiving.request(ids.eventA, origin.installation_id);
  assert.equal(copiedRequest.result.request.state, 'completed');
  assert.equal(copiedRequest.result.request.request_id, ids.eventA);
  const onward = await receiving.snapshot(join(transfer, 'received-onward.tar.gz'), ids.onward);
  await retained('COMPLETE_RECEIVING.json', {snapshot, snapshotAgain, independent, independentAgain,
    receivedHistory, copiedRequest, onward});
  const receivedOperator = await launchRole(operatorType, {directory: destination, python, port: 0});
  const receivedURL = await until(async () => {
    try { return JSON.parse(await readFile(join(receivedOperator.directory, 'application-url.json'), 'utf8')); }
    catch (error) { if (error.code === 'ENOENT') return null; throw error; }
  }, 'Independently received original operator');
  assert.equal(receivedURL.original.installation_id, independent.installation.installation_id);
  await stop(receivedOperator.child); await receivedOperator.observer.close();
  await stage('complete native TAR.GZ receiving, copied request journal and onward export',
    {origin: origin.installation_id, received: independent.installation.installation_id,
      archive_bytes: (await lstat(archive)).size, archive_sha256: digest(await readFile(archive)),
      received_source: independent.installation.source_identity});
  report.complete = true;
  report.completed_at = new Date().toISOString();
  report.received_installation = independent.installation;
} catch (error) {
  report.error = {code: error.code ?? error.name, message: error.message, stack: error.stack};
  process.exitCode = 1;
} finally {
  await Promise.allSettled([...children].map(stop));
  if (owner) await owner.close();
  await Promise.allSettled([...clients].map(client => client.close()));
  await writeFile(join(root, 'RESULT.json'), JSON.stringify(report, null, 2) + '\n', {mode: 0o600});
  process.stdout.write(JSON.stringify({complete: report.complete, stages: report.stages.length,
    result_file: join(root, 'RESULT.json'), ...(report.error ? {error: report.error} : {})}) + '\n');
}

